/*******************************************************************//**
PURPOSE: Get all edges that are 'Spine'

NOTES:
***********************************************************************/
SmStatus SmPolyBrep::GetSpinePolyEdges
 ( SmTArray<SmPolyEdge*> & rSpineEdges ) 
 const
{
    rSpineEdges.ReSet();
    SM_PTR_ARRAY(sEdges,SmPolyEdge,512);
    this->GetPolyEdges(sEdges);
    ULONG ii;
    for(ii=0; ii<sEdges.GetSize(); ii++) {
        SmPolyEdge *pPEdge = sEdges[ii];
        if ( pPEdge->IsSpine() ) {
            rSpineEdges.Add(pPEdge);

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE;
            if(bDebugMe) {
                ULONG lLamina = 0;
                ULONG lNonManifold = 0;
                ULONG lManifold = 0;
                SmPolyFace * pF = pPEdge->GetPolyFace();
                pF->GetPolyFaceDetail(lLamina,lNonManifold,lManifold);
                smgfx_SetLook(2,4, 1,0,0); pPEdge->Draw(); sm_GraphicsLoop();
                sm_GraphicsLoop();
            }
#endif // SM_DEBUG_CODE

        }
    }

    return SM_SUCCESS;

} // end SmPolyBrep::GetSpinePolyEdges

