/*******************************************************************//**
PURPOSE: Get a list of all PolyFace objects owned by
         this PolyBrep object or all PolyFace objects
         sharing a common m_pOriginalFace pointer value.

NOTES: rArray is ReSet prior to being loaded with m_pList elements
***********************************************************************/
void SmPolyBrep::GetPolyFaces
  (SmTArray<SmPolyFace*> & rPolyFaces,         // out: PolyFaces under m_pList doublyLinked list of m_pNext and m_pLast pointers
   SmFace                * pOptCommonFace) // in : include only PolyFaces with backptrs to this CommonFace, NULL to ignore
                                           //      default:[NULL]
 const
// eff: place m_pList linked list items into input rPolyFaces
{
  // init output
  rPolyFaces.ReSet();

  // locals
  ULONG ii ;
  SM_PTR_ARRAY(sPolyShells,     SmPolyShell,  16) ; // SmTArray<SmPolyShell*> 
  SM_PTR_ARRAY(sPolyShellFaces, SmPolyFace,  256) ; // SmTArray<SmPolyFace*>  

  // get all PolyBrep Shells
  GetPolyShells(sPolyShells);

  // no work - no PolyShells
  if(sPolyShells.GetSize() == 0)
    { return ; }

  // no pOptCommonFace branch
  if(pOptCommonFace == NULL)
    {
      // for every shell - load all PolyFaces into output
      for (ii=0; ii<sPolyShells.GetSize(); ii++) 
        {
          SmPolyShell *pPolyShell = sPolyShells[ii];
          if (ii==0) { pPolyShell->GetPolyFaces(rPolyFaces); }
          else       { pPolyShell->GetPolyFaces(sPolyShellFaces); rPolyFaces.Append(sPolyShellFaces); }
        }
    } // end pOptCommonFace == NULL branch

  else // pOptCommonFace != NULL branch
    {
      // locals
      ULONG lNumPolyFaces = 0 ;

      // get output size
      for (ii=0; ii<sPolyShells.GetSize(); ii++) 
        {
          SmPolyShell *pPolyShell = sPolyShells[ii];
          lNumPolyFaces += pPolyShell->GetSize() ;
        }

      // size output
      rPolyFaces.SetSize(lNumPolyFaces);
      rPolyFaces.ReSet();

      // for every PolyShell
      for (ii=0; ii<sPolyShells.GetSize(); ii++) 
        {
          SmPolyShell *pPolyShell = sPolyShells[ii];

          // for nonNULL m_pList pointers
          if (pPolyShell->GetList() != NULL)
            {
              // add all m_pList->m_pNext elements to rPolyFaces
              SmPolyFace *pPolyShellFace = (SmPolyFace*) pPolyShell->GetList() ;

              // keep walking circular List back to head element
              do{
                  // adding each elem to rPolyFaces
                  if(pOptCommonFace == pPolyShellFace->GetOriginalFace()) 
                    { rPolyFaces.Add(pPolyShellFace); }
                  pPolyShellFace = (SmPolyFace*) pPolyShellFace->m_pNext;

                } while (pPolyShellFace && (pPolyShellFace != pPolyShell->GetList()));

            }  // end PolyShell has PolyFace check
        } // end iter every PolyShell
    } // end pOptCommonFace != NULL branch

} // end SmPolyBrep::GetPolyFaces

