/*******************************************************************//**
PURPOSE: Constructor for a PolyFace 
  which can optionally create new PShells and PRegions and
  can optionally connect new PFace to containing PShell, PRegion, and PBrep.

NOTES: Optional pOptPtr values control 
  - creation of new PolyRegions and/or PolyShells, and
  - setting  of PolyBrep->PolyRegion->PolyShell->PolyFace connect relationships.

intended use: pOptPtr values are set to NotNULL one at a time, as:

+---------------------------------------------+----------------------------------+        
|Optinal Ptr Args                             |Action                            |
+---------------------------------------------+----------------------------------+        
|SmPolyFace(dTol);                            |Standalone PFace                  |
|                               --------------|----------------------------------|
|SmPolyFace(dTol, pPBrep);                    |new PShell, new PRegion,          |     
|                                             |set PBrep->PRegion->PShell->PFace |       
|                                       ------|----------------------------------|
|SmPolyFace(dTol, notUsed, pPRegion);         |new PShell,                       |     
|                                             |set PRegion->PShell->PFace        |     
|                                            -|----------------------------------|
|SmPolyFace(dTol, notUsed, notUsed, pPShell); |set PShell->PFace                 |     
+---------------------------------------------+----------------------------------+        

EXAMPLE: When building a PolyBrep up from a set of polygon facets
    (common during reads) create a PolyBrep where every PolyFace
    has its own PolyShell and PolyRegion with a sequence of PolyFace
    constructions followed by a single call to Stitch() to build a 
    solid model of the polygons. The code might look something like:

    // build 3 PolyVertices, 1 PolyFace, 1 PolyShell, 1 PolyRegion per facet
    pPShell = NULL ;
    for(ii=0;<lFacetCnt++;ii++)
      {
        pPolyFace = new (pPBrep) SmPolyFace(dTol, pPBrep, NULL, pPShell) ;

        // scheme to build just 1 PolyShell for all PolyFaces
        //   pPShell = NULL on 1st iter, a PolyShell will be built for pPolyFace
        //   pPShell = notNULL on subsequent iters, pPShell will own all new PolyFaces
        if(pPShell = NULL) { pPShell = pPolyFace->GetPolyShell(); }

        pPolyVertex0 = new (pPBrep) SmPolyVertex(sFacets[ii][0], dTol) ; 
        pPolyVertex1 = new (pPBrep) SmPolyVertex(sFacets[ii][1], dTol) ; 
        pPolyVertex2 = new (pPBrep) SmPolyVertex(sFacets[ii][2], dTol) ;
        // hint: Odds are the Facet point positions are used multiple times.
        //       For performance, don't duplicate PolyVertex nodes if you don't have to.  

        SmPolyLoop *pPolyLoop = NULL ;
        pPolyFace->StartPolyEdgeLoop(pPolyLoop) ;
        pPolyLoop->AddPolyEdge(dTol, sFacets[ii][0], sFacets[ii][1], pPolyVertex0, pPolyVertex1, pPBrep, &pPolyEdge0) ;
        pPolyLoop->AddPolyEdge(dTol, sFacets[ii][1], sFacets[ii][2], pPolyVertex1, pPolyVertex2, pPBrep, &pPolyEdge0) ;
        pPolyLoop->AddPolyEdge(dTol, sFacets[ii][2], sFacets[ii][0], pPolyVertex2, pPolyVertex0, pPBrep, &pPolyEdge0) ;
        pPolyLoop->FinishPolyEdgeLoop()
        . . .
      }
    
    // connect adjacent SmPolyFaces to use common PolyVertices, PolyEdges 
    //   and organized into connected PolyShells and PolyRegions
    pPBrep->Stitch() ;
***********************************************************************/
SmPolyFace::SmPolyFace
 (SmZoneTol3d    sZoneTol3d,     // in : tol to store with new PolyFace
  SmPolyBrep   * pOptPolyBrep,   // in : if(pOptPolyShell==NULL && pOptPolyShell==NULL)
                                 //        NotNULL = Make NewPolyRegion in pOptPolyBrep, 
                                 //                  Make NewPolyShell in NewPolyRegion,
                                 //                  Make this PolyFace in NewPolyShell
                                 //        NULL    = error
  SmPolyRegion * pOptPolyRegion, // in : if(pOptPolyShell==NULL)
                                 //        NotNull = make NewPolyShell in pOptPolyRegion,
                                 //                  make this PolyFace in NewPolyShell 
  SmPolyShell  * pOptPolyShell,  // in : NotNULL = make this PolyFace in pOptPolyShell
  SmVector3d   * pOptFaceNormal) // in : Normal for Face when known, NULL=ignore, default:[NULL]
: m_pCPolyFace(NULL), 
  m_pOriginalFace(NULL), 
  m_sZoneTol3d(sZoneTol3d),
  m_dMaxDeviation(-SM_BIG_DOUBLE), 
  m_dSphereRadius(0.0), 
  m_lIndexValue(SM_UNDEF_ULONG)
{
  // inherited:     init:    after PostInsert
  // m_pList      = NULL ;   = NULL ;
  // m_lListSize  = 0 ;      = 0 ;
  // m_pListOwner = NULL     = pPolyRegion ;
  // m_pNext      = NULL     = NextShell or this when only one shell in pPolyRegion ;
  // m_pLast      = NULL     = LastShell or this when only one shell in pPolyRegion ;

  // inherited:     init:    after PostInsert
  // m_pList      = NULL ;   = NULL ;
  // m_lListSize  = 0 ;      = 0 ;
  // m_pListOwner = NULL ;   = pPolyShell ;
  // m_pNext      = NULL ;   = NextFace or this when only one Face in pPolyShell ;
  // m_pLast      = NULL ;   = LastFace or this when only one Face in pPolyShell ;

#ifdef USE_DEBUG_COUNTER
static ULONG lDebugCount1 = 0;
static ULONG lDebugCount2 = 0;
  m_lDebugCount = s_lFaceCount++;
  if(   m_lDebugCount == lDebugCount1
     || m_lDebugCount == lDebugCount2) 
    {
      SE(SM_ERR);
    }
#endif
  // locals
  SmPolyShell *pPolyShell = NULL ;
  
  // select PolyShell to contain this PolyFace
  if     (pOptPolyShell)  { pPolyShell                 = pOptPolyShell ; 
                          }
  else if(pOptPolyRegion) { SmPolyBrep * pPolyBrep     = pOptPolyRegion->GetPolyBrep();
                            pPolyShell                 = new (pPolyBrep) SmPolyShell(pOptPolyRegion);
                          }
  else if(pOptPolyBrep)   { SmPolyRegion * pPolyRegion = new (pOptPolyBrep) SmPolyRegion(pOptPolyBrep);
                            if(!pPolyRegion) { SE(SM_ERR); return ; }
                            pPolyShell                 = new (pOptPolyBrep) SmPolyShell(pPolyRegion);
                          }

  // when asked - save PolyFace normal
  if(pOptFaceNormal)
    { m_vNormal = *pOptFaceNormal ;
      if(SM_SUCCESS != m_vNormal.Unitize())
        {
          m_vNormal.SetUninitialized() ; 
        } 
    }

  // check state - have to have a containing PolyShell
  if(!pPolyShell) 
    { 
      // PolyShell will be NULL when called from SmPolyMerge::MoveFace
      if(   pOptPolyShell  != NULL
         || pOptPolyRegion != NULL
         || pOptPolyBrep   != NULL) 
       { SE(SM_ERR); } 
      return; 
    }

  // add this PolyFace to the PolyShell
  pPolyShell->PostInsert(this);

} // end SmPolyFace constructor

/*******************************************************************//**
PURPOSE: Delete a poly face and remove it from its composite.

NOTES: 
***********************************************************************/
SmPolyFace::~SmPolyFace()
{
  // when member of CFace 
  if(m_pCPolyFace && m_pCPolyFace != this) 
    {
      // remove from owning CFace
      m_pCPolyFace->RemovePolyFace(this);
    }

  // clear all internal member values
  m_pCPolyFace                         = NULL ;
  m_pOriginalFace                      = NULL ;
  m_sZoneTol3d                         = SM_UNDEF_DOUBLE ;
  m_vNormal.SetUninitialized() ;
  m_dMaxDeviation                      = SM_UNDEF_DOUBLE ;
  m_vSphereCenter.SetUninitialized() ;
  m_dSphereRadius                      = SM_UNDEF_DOUBLE ;
  m_lIndexValue                        = SM_UNDEF_ULONG ;  
#ifdef USE_DEBUG_COUNTER
  m_lDebugCount                        = SM_UNDEF_ULONG ;
#endif
  m_lUserLong1                         = SM_UNDEF_ULONG ;
  m_lUserLong2                         = SM_UNDEF_ULONG ;
  m_lSmoothGroup                       = SM_UNDEF_ULONG ;

} // end SmPolyFace destructor

/*******************************************************************//**
PURPOSE: AssertValid() Test reporting static labels
***********************************************************************/
SmAssertReportLabel sAssertPolyFace_list[] =
{
 /*  0 */ {SM_AT_POINTER,     _T("Bad CPolyFace Context"),         _T("this PolyFace->context not the same as its owner m_pCPolyFace->context") },
 /*  1 */ {SM_AT_POINTER,     _T("Bad CPolyFace Back Pointer"),    _T("this PolyFace->m_pCPolyFace value equals this - it should point to a Composite PolyFace") }, 
 /*  2 */ {SM_AT_LIST,        _T("Bad CPolyFace List"),            _T("this PolyFace not in its m_pCPolyFace->PolyFace list") },
 /*  3 */ {SM_AT_POINTER,     _T("Bad Loop"),                      _T("PolyFace->m_pList of PolyLoops is NULL - PolyFace should have at least 1 PolyLoop") },
 /*  4 */ {SM_AT_POINTER,     _T("Bad Sibling PolyFace BackPtrs"), _T("PolyFace->pNext->pLast != pPolyFace") },
 /*  5 */ {SM_AT_POINTER,     _T("Bad Sibling PolyFace BackPtrs"), _T("PolyFace->pLast->pNext != pPolyFace") },
 /*  6 */ {SM_AT_TOPOLOGICAL, _T("Bad Loop Order"),                _T("PolyFace->1st PolyLoop orientation not SM_OT_SAME") },
 /*  7 */ {SM_AT_TOPOLOGICAL, _T("Bad Loop Order"),                _T("PolyFace->After 1st PolyLoop orientation not SM_OT_OPPOSITE") },
 /*  8 */ {SM_AT_TOPOLOGICAL, _T("Bad Loop Orienation"),           _T("PolyFace has more than 1 SM_OT_SAME oriented PolyLoops, must have just 1.") }
} ;                                                                                                                                                            

/*******************************************************************//**
PURPOSE:

NOTES: 1. skips checks when IsMarked(SM_MT_MARKASSERT) else marks this object.
       2. if(eWalkTree == SM_WALK) call AssertValid on every PolyLoop.

RETURNS ---  TRUE  = OK
             FALSE = Problem
  Does not cascade Asserts from other AssertValid() calls.
***********************************************************************/
SmBoolean SmPolyFace::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL] 
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests, 
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests 
                                    //      default:[SM_LEVEL_0] 
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK] 
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  // init rtn value
  SmBoolean bOk, bRtn = TRUE ; 

  // skip already marked objects - set this mark
  if(IsMarked(SM_MT_MARKASSERT))
    { 
      return(bRtn) ; 
    }
  ((SmPolyFace*)this)->Mark(SM_MT_MARKASSERT) ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmOwningTopology::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests) 
           : TRUE ) ; 

  // SmPolyFace checks
  // Derived class checks are different, so we need to know that.
  // SmCPolyFace is derived from SmPolyFace
  SmBoolean bIsBaseClass = ( GetType() == SmPolyFace_TYPE );

  // when this PolyFace is part of a CPolyFace
  if( m_pCPolyFace != NULL )
    {
      // Context check
      bOk = ( m_pCPolyFace->GetContext() == this->GetContext() ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (bOk), _T("") ) ;

      // When this is a base class SmPolyFace type (not a SmCPolyFace)
      if( bIsBaseClass )
        {
          // the Pointer to the CompositeFace can't be to itself
          bOk = ( m_pCPolyFace != this ); SM_ASSERT(bOk); 
          bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, (bOk), _T("") ) ;

          SM_PTR_ARRAY(sFaces, SmPolyFace, 256); // SmTArray<SmPolyFace*>
          m_pCPolyFace->GetPolyFacesOfComposite( sFaces );

          ULONG lIdx;
          bOk = sFaces.FindElement( (SmPolyFace*)this, lIdx ); SM_ASSERT(bOk); 
          bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (bOk), _T("") ) ;
        }
    }

  // PolyFace back pointers
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, this->GetNext()->GetLast() == this, _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, this->GetLast()->GetNext() == this, _T("") ) ;

  // check orientation on PolyLoops in ordered PolyLoop list
  ULONG lSameCount = 0 ;
  SM_PTR_ARRAY(sPolyLoops, SmPolyLoop, 8) ;
  GetPolyLoops(sPolyLoops) ;
  for(ULONG ii=0;ii<sPolyLoops.GetSize();ii++)
    {
       SmPolyLoop  * pPolyLoop = sPolyLoops[ii] ;
       SmOrientType  eOrient   = pPolyLoop->GetOrientation() ;

       /*  6 */ // PolyFace->1st PolyLoop orientation not SM_OT_SAME
       /*  7 */ // PolyFace->After 1st PolyLoop orientation not SM_OT_OPPOSITE
       if(ii==0) { bRtn &= SM_ASSERT_BOOLEAN_REPORT(6, SM_LEVEL_0, eOrient == SM_OT_SAME, _T("") ) ; }
       else      { bRtn &= SM_ASSERT_BOOLEAN_REPORT(7, SM_LEVEL_0, eOrient == SM_OT_OPPOSITE, _T("") ) ; }

       if(eOrient == SM_OT_SAME)
         { lSameCount++ ; }
      
    } // end iter every PolyLoop

  /*  8 */ // PolyFace has more than 1 SM_OT_SAME oriented PolyLoops, must have just 1
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(8, SM_LEVEL_0, sPolyLoops.GetSize() == 0 || lSameCount == 1, _T("")) ;

  // Pass the call down.
  if( m_pList != NULL )
    {
      SmTopology *pTgt = m_pList;
      do
        {
          SmPolyLoop *pLoop = SM_CAST_PTR( SmPolyLoop, pTgt );
          if( pLoop == NULL ) 
               { bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, (FALSE), _T("") ) ; }
          else {  if(eWalkTree == SM_WALK) { bRtn &= pLoop->AssertValid(pAList, eTestLevel, eWalkTree); }
               }

          pTgt = pTgt->GetNext();

        } while ( pTgt != m_pList );
    }

  // all done
  // SM_ASSERT(bRtn) ;
  return(bRtn) ;

} // end SmPolyFace::AssertValid

