/*******************************************************************//**
PURPOSE: Draw the PolyVertex Point

NOTES: 
***********************************************************************/
SmDisplayList * SmPolyEdge::Draw
 (SmBoolean       bDrawRaw,     // in : TRUE = draw pts in NativeSpace, default:[TRUE]
  SmBoolean       bDrawIn3D,    // in : TRUE = if Is2dOrZero(), draw pts after projecting through OrigSurf, default:[FALSE]
  SmPlane       * pOptOutPlane, // in : When bDrawRaw==TRUE, Draw on this plane, NULL=draw on z=0 plane, default:[NULL]
  SmGfxArraySet * pOptGfxSet)   // i/o: used for OpenGL ES 2.0. When given, accumulate GfxVertexArrays not GL calls.
                                //      NULL to ignore. default:[NULL]
 const
{
  SmDisplayList *pRtn = NULL ;

#ifdef SM_GFX_CODE 
   
  // locals: Global display parameters
  const SmDisplayParameters &crDisp = smgfx_RefGlobalDisplayParameters() ;

  // locals
  SmVector3d sColor  = smgfx_GetColor() ;
  SmPoint3d sStartPt = GetStartPoint() ;
  SmPoint3d sEndPt   = GetEndPoint() ;

  // start new displayList (unless one is already open)
  smgfx_Open(smgfx_GetRuleColor(this), NULL, NULL, FALSE, pOptGfxSet);

  // when asked - pick color based on "Curvature" measured as the dihedral angle
  if(crDisp.m_bDrawCurvature == TRUE)
    {
      // GWC: replace the following two lines with the new calls (after current release)
      //   SmVector3d sDiAngColor ;
      //   GetDihedralAngRad(&sDiAngColor) ;
      
      // Dihedral AngRad range: [0-2Pi]
      double dDihedralAngRad = ComputeSectorAngle() ; // GWC: could be called GetDihedralAngRad() ;

      // pick a color based on the edges dihedral angle  // GWC: could be called GetDihedralAngColor() ;
      //   very red   for AngRad >> SM_PI, 
      //   very green for AngRad << SM_PI, 
      //   very blue  for AngRad == SM_PI
      SmVector3d sDiAngColor( (dDihedralAngRad > SM_PI ? smos_Sqrt((dDihedralAngRad - SM_PI) / SM_PI) : 0),
                              (dDihedralAngRad < SM_PI ? smos_Sqrt((SM_PI - dDihedralAngRad) / SM_PI) : 0),
                              (dDihedralAngRad > SM_PI ? 1.0 - smos_Sqrt((dDihedralAngRad - SM_PI) / SM_PI)
                                                       : 1.0 - smos_Sqrt((SM_PI - dDihedralAngRad) / SM_PI)) ) ;
      smgfx_OutputColor(sDiAngColor, pOptGfxSet) ;
    }

  // when asked - Draw PolyVertex in native space
  if(bDrawRaw)
    {
      // when asked - project through OptOutPlane
      if(pOptOutPlane)
        {
          SmPoint2d sStartUV(sStartPt.x, sStartPt.y) ;
          SmPoint2d sEndUV(sEndPt.x, sEndPt.y) ;
          SmPoint3d sStartOnPlane, sEndOnPlane ;
          pOptOutPlane->EvaluatePoint(sStartUV, sStartOnPlane) ;
          pOptOutPlane->EvaluatePoint(sEndUV, sEndOnPlane) ;

          smgfx_DrawPoint(sStartOnPlane.x,sStartOnPlane.y,sStartOnPlane.z, pOptGfxSet); 
          smgfx_DrawLine (sStartOnPlane.x,sStartOnPlane.y,sStartOnPlane.z, 
                          sEndOnPlane.x,sEndOnPlane.y,sEndOnPlane.z, pOptGfxSet);
        }
      else
        {
          // Draw the native space point and line
          smgfx_DrawPoint(sStartPt.x,sStartPt.y,sStartPt.z, pOptGfxSet);
          smgfx_DrawLine (sStartPt.x,sStartPt.y,sStartPt.z, sEndPt.x,sEndPt.y,sEndPt.z, pOptGfxSet);
        }
    } // end DrawRaw check

  // when asked - if possible, Draw PolyLoop projected through OrigSurf 
  if(bDrawIn3D && Is2dOrZero() && GetPolyBrep()->GetOKBackPtrs() )
    {
       SmPolyFace *pPolyFace = GetPolyFace();
       SmFace     *pOrigFace = (pPolyFace && pPolyFace->GetOKBackPtrs()) ? pPolyFace->GetOriginalFace() : NULL ;
       SmSurface  *pOrigSurf = pOrigFace ? pOrigFace->GetSurface() : NULL ;

       if(pOrigSurf)
         {
           SmPoint2d sUV ;

           // change PolyPoints in place - they won't be used again
           sUV.Set(sStartPt.x, sStartPt.y) ;
           pOrigSurf->EvaluatePoint(sUV, sStartPt) ;

           sUV.Set(sEndPt.x, sEndPt.y) ;
           pOrigSurf->EvaluatePoint(sUV, sEndPt) ;

           // Draw the 3d space point and line
           smgfx_DrawPoint(sStartPt.x,sStartPt.y,sStartPt.z, pOptGfxSet);
           smgfx_DrawLine (sStartPt.x,sStartPt.y,sStartPt.z, sEndPt.x,sEndPt.y,sEndPt.z, pOptGfxSet);

         } // end pOrigSurf existence check
     } // end bDrawIn3D && Is2d() == TRUE && GetPolyBrep()->GetOKBackPtrs() check

  // end new displayList
  pRtn = smgfx_Close(pOptGfxSet) ;

  // restore draw state
  smgfx_SetColor(sColor, pOptGfxSet) ;

#else
  SM_REF4(bDrawRaw, bDrawIn3D, pOptOutPlane, pOptGfxSet);
#endif // end SM_GFX_CODE
  return(pRtn) ;

} // end SmPolyEdge::Draw()

