/*******************************************************************//**
PURPOSE:

NOTES: 1. skips checks when IsMarked(SM_MT_MARKASSERT) else marks this object.

RETURNS ---  TRUE  = OK
             FALSE = Problem
  Does not cascade Asserts from other AssertValid() calls.
***********************************************************************/
SmBoolean SmPolyVertex::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL] 
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests, 
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests 
                                    //      default:[SM_LEVEL_0] 
  SmAssertWalking    eWalkTree,     // NotUsed: in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK] 
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  SM_REF1(eWalkTree) ;
  // init rtn value
  SmBoolean bOk, bRtn = TRUE ; 

  // skip already marked objects - set this mark
  if(IsMarked(SM_MT_MARKASSERT))
    { 
      return(bRtn) ; 
    }
  ((SmPolyVertex*)this)->Mark(SM_MT_MARKASSERT) ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmTopology::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests) 
           : TRUE ) ; 

  // todo - add SmPolyVertex checks here
  // There might be something we can check about the Edges incident on us.

  // Every PolyVertex must be attached to at least one PolyEdge
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (m_pPolyEdgeList != NULL), _T("") ) ;

  // consistent context check
  if( m_pPolyEdgeList != NULL ) 
    { 
      bOk = ( m_pPolyEdgeList->GetContext() == this->GetContext() ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, (bOk), _T("") ) ; 
    }

  // uninitialized PolyVertex
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (m_vPoint.IsUndef() == FALSE), _T("") ) ; 

  // PolyBrep->PolyVertex list back pointers
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, this->GetNext()->GetLast() == this, _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, this->GetLast()->GetNext() == this, _T("") ) ;


  // PolyVertex->PolyEdge list back pointers
  SM_PTR_ARRAY(sPolyVertexEdges, SmPolyEdge, 16) ;
  GetStartingPolyEdges(sPolyVertexEdges) ;

  for(ULONG ii=0;ii<sPolyVertexEdges.GetSize();ii++)
    {
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, sPolyVertexEdges[ii]->GetStartPolyVertex() == this, _T("") ) ;
    }

  // all done
  // SM_ASSERT(bRtn) ;
  return(bRtn) ;

} // end SmPolyVertex::AssertValid

