/*******************************************************************//**
PURPOSE: Draw the PolyVertex Point

NOTES: 
***********************************************************************/
SmDisplayList * SmPolyVertex::Draw
  (SmBoolean       bDrawRaw,       // in : TRUE = draw PolyLoop->PolyEdge->StartPts, default:[TRUE]
   SmBoolean       bDrawIn3D,      // in : TRUE = draw OrigSurf(PolyLoop->PolyEdge->StartPts), default:[FALSE] 
   SmPlane       * pOptOutPlane,   // in : When bDrawRaw==TRUE, Draw on this plane, NULL=draw on z=0 plane, default:[NULL]
  SmGfxArraySet  * pOptGfxSet)     // i/o: used for OpenGL ES 2.0. When given, accumulate GfxVertexArrays not GL calls.
                                   //      NULL to ignore. default:[NULL]
 const
{
  SmDisplayList *pRtn = NULL ;

#ifdef SM_GFX_CODE

  // start new displayList (unless one is already open)
  smgfx_Open(smgfx_GetRuleColor(this), NULL, NULL, FALSE, pOptGfxSet);

  // when asked - Draw PolyVertex in native space
  if(bDrawRaw)
    {
      // when asked - project through OptOutPlane
      if(pOptOutPlane)
        {
          SmPoint2d sPointUV(m_vPoint.x, m_vPoint.y) ;
          SmPoint3d sPointOnPlane ;
          pOptOutPlane->EvaluatePoint(sPointUV, sPointOnPlane) ;

          // Draw the native space point on plane
          smgfx_DrawPoint(sPointOnPlane.x, sPointOnPlane.y, sPointOnPlane.z, pOptGfxSet) ;
        }
      else // Draw data raw
        {
          // Draw the native space point
          smgfx_DrawPoint(m_vPoint.x, m_vPoint.y, m_vPoint.z, pOptGfxSet) ;
        }
     }

   // when asked - if possible, Draw PolyLoop projected through OrigSurf 
   if(bDrawIn3D && Is2dOrZero() && GetPolyBrep()->GetOKBackPtrs())
     {
        SmPolyEdge *pPolyEdge = GetFirstPolyEdge() ;
        SmPolyFace *pPolyFace = pPolyEdge ? pPolyEdge->GetPolyFace() : NULL ;
        SmFace     *pOrigFace = (pPolyFace && pPolyFace->GetOKBackPtrs()) ? pPolyFace->GetOriginalFace() : NULL ;
        SmSurface  *pOrigSurf = pOrigFace ? pOrigFace->GetSurface() : NULL ;

        if(pOrigSurf)
          {
            SmPoint2d sUV ;
            SmPoint3d sPoint3d ;

            // change PolyPoints in place - they won't be used again
            sUV.Set(m_vPoint.x, m_vPoint.y) ;
            pOrigSurf->EvaluatePoint(sUV, sPoint3d) ;

            // Draw the native space point
            smgfx_DrawPoint(sPoint3d.x, sPoint3d.y, sPoint3d.z, pOptGfxSet) ;

          } // end pOrigSurf existence check
      } // end bDrawIn3D && Is2dOrZero() == TRUE && GetPolyBrep()->GetOKBackPtrs() check

   // end new displayList
   pRtn = smgfx_Close(pOptGfxSet) ;

#else
  SM_REF4(bDrawRaw, bDrawIn3D, pOptOutPlane, pOptGfxSet);
#endif // end SM_GFX_CODE
  return(pRtn) ;

} // end SmPolyVertex::Draw()

/*******************************************************************//**
PURPOSE:
NOTES:
***********************************************************************/
SmBoolean SmPolyVertex::IsKindOf( SM_TYPE t ) const
{
  return ((SmPolyVertex_TYPE == t) ? TRUE : SmTopology::IsKindOf( (t) ));
}

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyVertex::Dump(void) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  // locals
  ULONG ii ;
  SM_PTR_ARRAY(sEdges,   SmPolyEdge, 16) ; // SmTArray<SmPolyEdge*>  
  SM_PTR_ARRAY(sRadials, SmPolyEdge, 16) ; // SmTArray<SmPolyEdge*>  
 
  GetPolyEdges( sEdges );
  ULONG lNumEdges = sEdges.GetSize();

  // header
  smos_sprintf(sBuff,       _T("\nPolyVertex:[0x%p] = lNumEdges:[%ld], Tol:[%16.16lf], IndexVal:[%ld], OrigVertex:[0x%p], Point:"),
             this,
             lNumEdges,
             (double)m_sZoneTol3d,
             m_lIndexValue,
             m_pOriginalVertex);
  smos_sprintf(sBuffForFile,_T("\nPolyVertex:[%s] = lNumEdges:[%ld], Tol:[%16.16lf], IndexVal:[%ld], OrigVertex:[0x%p], Point:"),  
             _T("notNULL"),
             lNumEdges,
             (double)m_sZoneTol3d,
             m_lIndexValue,
             m_pOriginalVertex );
  smos_WriteBuffer(sBuff, sBuffForFile);

  // point
  m_vPoint.Dump();
  smos_WriteBuffer(_T("\n"));

  // edges
  for(ii=0;ii<lNumEdges;ii++)
    {
      SmPolyEdge *pPE = sEdges[ii];
      pPE->GetAllRadials( sRadials );
      smos_sprintf(sBuff       ,_T("\n   PolyEdge %3ld:[0x%p] = RadialCnt:[%ld]"), 
                 ii, 
                 pPE, 
                 sRadials.GetSize() );
      smos_sprintf(sBuffForFile,_T("\n   PolyEdge %3ld:[0x%p] = RadialCnt:[%ld]"), 
                 ii, 
                 pPE, 
                 sRadials.GetSize() );
      smos_WriteBuffer(sBuff, sBuffForFile);
    }

  // all done
 // smos_WriteBuffer(_T("\n"));  // gwc this is not needed

} // end SmPolyVertex::Dump

