/*******************************************************************//**
PURPOSE:

NOTES: 1. skips checks when IsMarked(SM_MT_MARKASSERT) else marks this object.
       2. if(eWalkTree == SM_WALK) call AssertValid on Start PolyVertex.

RETURNS ---  TRUE  = OK
             FALSE = Problem
  Does not cascade Asserts from other AssertValid() calls.
***********************************************************************/
SmBoolean SmPolyEdge::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL] 
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests, 
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests 
                                    //      default:[SM_LEVEL_0] 
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK] 
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{

  // locals and init rtn value
  SmBoolean        bOk, bRtn = TRUE ; 
  const SmContext *pContext = this->GetContext();

  // skip already marked objects - set this mark
  if(IsMarked(SM_MT_MARKASSERT))
    { 
      return(bRtn) ; 
    }
  ((SmPolyEdge*)this)->Mark(SM_MT_MARKASSERT) ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmTopology::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests) 
           : TRUE ) ; 

  // doubly linked list checks - Next and Prev items must point back to this one
  //                           - No NULL pointers allowed for closed circular lists
    {
      /* 15 */ // NextRadialEdge BackPointer check
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(15, SM_LEVEL_0, (m_pNextRadialE != NULL), _T("") ) ;
      
      /*  0 */ // Bad NULL Pointer, pPolyEdge->m_pNextRadialE ptr is NULL - should be part of a closed PtrLoop
      bOk = ( m_pNextRadialE == NULL || m_pNextRadialE->m_pLastRadialE == this ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (bOk), _T("") ) ;

      // LastRadialEdge BackPointer check
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(16, SM_LEVEL_0, (m_pLastRadialE != NULL), _T("") ) ;
      
      /*  1 */ //Bad Back Pointer, pPolyEdge->m_pLastEdgeAtV->m_pNextRadialE != this pPolyEdge
      bOk = ( m_pLastRadialE == NULL || m_pLastRadialE->m_pNextRadialE == this ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, (bOk), _T("") ) ;

      // NextEdgeAtV BackPointer check
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(17, SM_LEVEL_0, (m_pNextEdgeAtV != NULL), _T("") ) ;
      bOk = ( m_pNextEdgeAtV == NULL || m_pNextEdgeAtV->m_pPrevEdgeAtV == this ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (bOk), _T("") ) ;

      // PrevEdgeAtV BackPointer check
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(18, SM_LEVEL_0, (m_pPrevEdgeAtV != NULL), _T("") ) ;
      bOk = ( m_pPrevEdgeAtV == NULL || m_pPrevEdgeAtV->m_pNextEdgeAtV == this ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, (bOk), _T("") ) ;

      // CCW LoopNeighbor BackPointer check
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(19, SM_LEVEL_0, (GetNext() != NULL), _T("") ) ;
      bOk = ( GetNext() == NULL || GetNext()->GetLast() == this ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(12, SM_LEVEL_0, (bOk), _T("") ) ;

      // CW LoopNeighbor BackPointer check
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(20, SM_LEVEL_0, (GetLast() != NULL), _T("") ) ;
      bOk = ( GetLast() == NULL || GetLast()->GetNext() == this ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(13, SM_LEVEL_0, (bOk), _T("") ) ;

      // PolyLoop Owner
      /* 25 */ // Bad NULL Pointer, PolyEdge->m_pListOwner PolyLoop Ptr == NULL
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(25, SM_LEVEL_0, (GetOwner() != NULL), _T("") ) ;

   } // end doubly linked list checks

  // Context checks - TopoObj contexts should be the same
    {
      // next Radial Edge common context
      bOk = ( m_pNextRadialE->GetContext() == pContext ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, (bOk), _T("") ) ;

      // last Radial Edge common context
      bOk = ( m_pLastRadialE->GetContext() == pContext ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(6, SM_LEVEL_0, (bOk), _T("") ) ;

      // NextEdgeAtV common context
      bOk = ( m_pNextEdgeAtV->GetContext() == pContext ); SM_ASSERT(bOk);
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(7, SM_LEVEL_0, (bOk), _T("") ) ;
      
      // PrevEdgeAtV common context
      bOk = ( m_pPrevEdgeAtV->GetContext() == pContext ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(8, SM_LEVEL_0, (bOk), _T("") ) ;
      
      // StartPolyVertex common context
      bOk = ( m_pPolyVertex->GetContext() == pContext ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(9, SM_LEVEL_0, (bOk), _T("") ) ;
    
      // CCW LoopNeighbor common context
      bOk = ( GetNext()->GetContext() == pContext ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(10, SM_LEVEL_0, (bOk), _T("") ) ;
      
      // CW LoopNeighbor common context
      bOk = ( GetLast()->GetContext() == pContext ); SM_ASSERT(bOk); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(11, SM_LEVEL_0, (bOk), _T("") ) ;
    
    } // end context checks

  // Every PolyEdge must have a PolyVertex
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(21, SM_LEVEL_0, (m_pPolyVertex != NULL), _T("") ) ;

  // Every PolyEdge must have a length
  SmScaledZero dScaledZero = SmTol::GetScaledZero() ;
  double dLength = GetLength() ;
  bRtn &= SM_ASSERT_VALUE_REPORT(22, SM_LEVEL_0, SmTol::OutOfTol(dScaledZero, dLength), dScaledZero, dLength, _T("")) ;

  // PolyEdge should not be so short as to connect coincident end vertices
  double dTol = GetStartPolyVertex()->GetTolerance() + GetEndPolyVertex()->GetTolerance() ;
  bRtn &= SM_ASSERT_VALUE_REPORT(24, SM_LEVEL_0, (dTol < GetLength()), dTol, GetLength(), _T("")) ;

  // Can't think of any SmPolyVertAuxData checks

  // Check that the circular doubly-linked list is correct.
  // Look for loops in the list that don't include the first element.  // GWC:???
  // Method: walk the list with two pointers, with one going only
  // half as fast as the other.  (Step every 2nd iteration.)
  // If there is a loop in the list, the faster pointer will
  // catch up with the slower, and they'll be equal at some point.

  //SmPolyEdge * pCurr        = this->m_pNextRadialE;
  //SmPolyEdge * pTrailer     = pCurr;
  //SmBoolean    bMoveTrailer = FALSE;

  // GWC: talked to bill - the following check catches linked lists
  //      with bad internal loops as: A -> B -> C -> B.
  //      But the doubly linked list checks above catch the
  //      same problems - so removing.
    //  bOk = TRUE;
    //  while ( pCurr != this && pCurr != NULL ) // these ptrs can be Null.
    //    {
    //      // Check back pointers next/last - GWC: optional this check is already done
    //      bOk &= pCurr->m_pNextRadialE->m_pLastRadialE == pCurr;
    //      bOk &= pCurr->m_pLastRadialE->m_pNextRadialE == pCurr;
    //  
    //      pCurr = pCurr->m_pNextRadialE;
    //      if ( bMoveTrailer )
    //        { pTrailer = pTrailer->m_pNextRadialE; }
    //      bMoveTrailer = !bMoveTrailer;  // every 2nd time.
    //  
    //      if ( pTrailer == pCurr )
    //        {
    //          bOk = FALSE; // Found a loop before getting back to start.
    //          break;
    //        }
    //    }
    //  bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, (bOk), _T("") ) ;
    //  bRtn &= bOk;

  // Do some geometric tests: 
  // 1. faces folding back on each other.
  //    Tol: Some users require very narrow angles.  [B288]
  // Make it static so that we can change it in the debugger.
  constexpr double dMinAngDeg = 0.0005;

  // no work - lamina edge does not have paired neighbor faces
  //         - Edges not connected to PolyLoops or PolyFaces are not part of a face pair
  if(!IsLamina() && GetPolyLoop() != NULL && GetPolyFace() != NULL)
    {
      double dAngDeg = SM_RAD2DEG( ComputeSectorAngle() );

      // for zero dihedral angles that make the nieghbor faces coincident
      if ( dAngDeg < dMinAngDeg || dAngDeg > 360 - dMinAngDeg )
        {
          bRtn &= SM_ASSERT_BOOLEAN_REPORT(14, SM_LEVEL_1, (FALSE), _T("") ) ; 

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe2=FALSE;
          if ( bDebugMe2 ) 
            {
              SmPolyFace *pPF1 = GetPolyFace();
              SmPolyEdge *pRad = GetRadial();
              SmPolyFace *pPF2 = (pRad) ? pRad->GetPolyFace() : NULL ;

              if ( FALSE ) {
                  smgfx_Erase();
                  smgfx_SetLook( 1,2, 0,0,0 ); this->GetPolyBrep()->Draw(); sm_GraphicsLoop();
              }
              smgfx_SetLook( 5,7, 1,0,0 ); Draw(); sm_GraphicsLoop();
              smgfx_SetLook( 3,5, 0,0,1 ); if(pPF1) pPF1->DrawDebug(); sm_GraphicsLoop();
              smgfx_SetLook( 3,5, 0,1,0 ); if(pPF2) pPF2->DrawDebug(); sm_GraphicsLoop();
              sm_GraphicsLoop();
            }
#endif // SM_DEBUG_CODE

        } // end if zero dihedral angle
    } // end not Lamina edge check for upcoming dihedral angle check

  // Every Edge sharing common vertices must be radial partners 
  ULONG ii, nFoundIndex ;
  SmPolyVertex *pEndVertex = GetEndPolyVertex() ;
  SM_PTR_ARRAY(sRadials,     SmPolyEdge, 16) ;
  SM_PTR_ARRAY(sVertexEdges, SmPolyEdge, 16) ;
  GetAllRadials(sRadials) ;
  m_pPolyVertex->GetPolyEdges(sVertexEdges) ;
  for(ii=0;ii<sVertexEdges.GetSize();ii++)
    {
      if(sVertexEdges[ii]->GetOtherPolyVertex(m_pPolyVertex) == pEndVertex)  
        {
          bRtn &= SM_ASSERT_BOOLEAN_REPORT(23, SM_LEVEL_0, TRUE == sRadials.FindElement(sVertexEdges[ii], nFoundIndex), _T("")) ; 
        }
    } // end iter every sStartVertexEdge

  // walk topology graph - call vertex
  if(eWalkTree == SM_WALK) { bRtn &= m_pPolyVertex->AssertValid(pAList, eTestLevel, eWalkTree); }
    
  // all done
  // SM_ASSERT(bRtn) ;
  return(bRtn) ;

} // end SmPolyEdge::AssertValid

