/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyEdge::Dump(void) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  // locals
  ULONG ii ;
  SmPolyVertex * pStartPolyVertex = GetStartPolyVertex();
  SmPolyEdge   * pCCWPolyEdge     = GetCCWPolyEdge() ;
  SmPolyEdge   * pCWPolyEdge      = GetCWPolyEdge() ;
  SmPoint3d      sStartPoint      = pStartPolyVertex->GetPoint();
  SmPoint3d      sCCWPoint        = pCCWPolyEdge->GetStartPoint() ;
  SmPoint3d      sCWPoint         = pCWPolyEdge->GetStartPoint() ;
  SM_PTR_ARRAY  (sRadials, SmPolyEdge, 16) ; // SmTArray<SmPolyEdge*>  
  GetAllRadials( sRadials );
  ULONG          lNumRadials      = sRadials.GetSize();

  // edge header
  smos_sprintf(sBuff,       _T("\nPolyEdge:[0x%p] = StartPVert:[0x%p]=[%lf  %lf  %lf], Length:[%16.16lf], Tol:[%16.16lf], OrigEdgeuse:[0x%p], IndxVal=%ld"),
             this,
             pStartPolyVertex,
             sStartPoint.x, sStartPoint.y, sStartPoint.z,
             Length(),
             (double)m_sZoneTol3d,
             m_pOriginalEdgeuse,
             m_lIndexValue);
  smos_sprintf(sBuffForFile,_T("\nPolyEdge:[%s] = StartPVert:[%s]=[%lf  %lf  %lf], Length:[%16.16lf], Tol:[%16.16lf], OrigEdgeuse:[%s], IndxVal=%ld"), 
             _T("notNULL"),
             pStartPolyVertex ? _T("notNULL") : _T("NULL"),
             sStartPoint.x, sStartPoint.y, sStartPoint.z,
             Length(),
             (double)m_sZoneTol3d,
             m_pOriginalEdgeuse ? _T("notNULL") : _T("NULL"),
             m_lIndexValue);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // PolyLoop neighbors
  smos_sprintf(sBuff,       _T("\n  next_CCWPEdge:[0x%p]=[%lf  %lf  %lf], last_CWPEdge:[0x%p]=[%lf  %lf  %lf]"),
             pCCWPolyEdge, 
             sCCWPoint.x, sCCWPoint.y, sCCWPoint.z,
             pCWPolyEdge, 
             sCWPoint.x, sCWPoint.y, sCWPoint.z);
  smos_sprintf(sBuffForFile,_T("\n  next_CCWPEdge:[%s]=[%lf  %lf  %lf], last_CWPEdge:[%s]=[%lf  %lf  %lf]"),
             pCCWPolyEdge ? _T("notNULL") : _T("NULL"), 
             sCCWPoint.x, sCCWPoint.y, sCCWPoint.z,
             pCWPolyEdge ? _T("notNULL") : _T("NULL"), 
             sCWPoint.x, sCWPoint.y, sCWPoint.z);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // radial neighbors
  smos_sprintf(sBuff,       _T("\n  NumRadials=%ld = ["), lNumRadials );
  smos_WriteBuffer(sBuff);

  // for every radial
  for(ii=0;ii<lNumRadials;ii++)
    {
      SmPolyEdge * pRadialPolyEdge = sRadials[ii];
      double       dSectorAngDeg   = SM_RAD2DEG( pRadialPolyEdge->ComputeSectorAngle() );
      SmPolyFace * pPolyEdgeFace   = pRadialPolyEdge->GetPolyFace();

      smos_sprintf(sBuff       ,_T("PEdge:[0x%p] PFace:[0x%p] AngleDeg:[%lf]"), 
                 pRadialPolyEdge, 
                 pPolyEdgeFace, 
                 dSectorAngDeg);
      smos_sprintf(sBuffForFile,_T("PEdge:[%s] PFace:[%s] AngleDeg:[%lf]"), 
                 pRadialPolyEdge ? _T("notNULL") : _T("NULL"), 
                 pPolyEdgeFace   ? _T("notNULL") : _T("NULL"), 
                 dSectorAngDeg);
      smos_WriteBuffer(sBuff, sBuffForFile);

      if(ii<lNumRadials-1) { smos_WriteBuffer(_T(", ")) ; }
      else                 { smos_WriteBuffer(_T("]")) ;  }
    }

  // neighbors at vertex
  smos_sprintf(sBuff,       _T("\n  NextEdgeAtVertex:[0x%p], PrevEdgeAtVertex:[0x%p]"),
             m_pNextEdgeAtV, 
             m_pPrevEdgeAtV);
  smos_sprintf(sBuffForFile,_T("\n  NextEdgeAtVertex:[0x%p], PrevEdgeAtVertex:[0x%p]"),
             m_pNextEdgeAtV ? _T("notNULL") : _T("NULL"), 
             m_pPrevEdgeAtV ? _T("notNULL") : _T("NULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

  // Aux data
  if(m_pAuxData) { smos_sprintf(sBuff,       _T("\n  AuxData:[0x%p] = NumUsers=%ld, IndxVal=%ld, UV:[%lf, %lf], Normal:[%lf, %lf, %lf]"),
                              m_pAuxData,
                              m_pAuxData->GetNumUsers(), 
                              m_pAuxData->GetIndexValue(), 
                              m_pAuxData->m_vUV.x, m_pAuxData->m_vUV.y, 
                              m_pAuxData->m_vNormal.x, m_pAuxData->m_vNormal.y, m_pAuxData->m_vNormal.z) ; 

                   smos_sprintf(sBuffForFile,_T("\n  AuxData:[0x%p] = NumUsers=%ld, IndxVal=%ld, UV:[%lf, %lf], Normal:[%lf, %lf, %lf]"),
                              m_pAuxData,
                              m_pAuxData->GetNumUsers(), 
                              m_pAuxData->GetIndexValue(), 
                              m_pAuxData->m_vUV.x, m_pAuxData->m_vUV.y, 
                              m_pAuxData->m_vNormal.x, m_pAuxData->m_vNormal.y, m_pAuxData->m_vNormal.z) ; 
                   smos_WriteBuffer(sBuff, sBuffForFile);
                 }
  else           { smos_WriteBuffer(_T("\n  AuxData:[NULL]")) ;
                 }

  // all done
 // smos_WriteBuffer(_T("\n")) ;  // GWC: This is not needed

} // end SmPolyEdge::Dump

