/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyLoop::Dump(void) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  // locals
  ULONG ii  ;
  SM_PTR_ARRAY(sPolyEdges, SmPolyEdge, 64) ; // SmTArray<SmPolyEdge*>  
  GetPolyEdges(sPolyEdges);
  ULONG        lNumPolyEdges = sPolyEdges.GetSize();   

  // PolyLoop header
  smos_sprintf(sBuff,       _T("\nPolyLoop:[0x%p] = NumPEdges=%ld, Orient:[%s], Closed:[%s], LastPVert:[0x%p], LastPos[%lf %lf %lf]"),
             this, 
             lNumPolyEdges,
             m_eOrientation == SM_OT_SAME ? _T("SM_OT_SAME=OuterLoop") : _T("SM_OT_OPPOSITE=InnerLoop"),
             m_bClosed ? _T("TRUE") : _T("FALSE"),
             m_pLastEndPolyVertex,
             m_sLastEndPoint.x, m_sLastEndPoint.y, m_sLastEndPoint.z) ;
  smos_sprintf(sBuffForFile,_T("\nPolyLoop:[%s] = NumPEdges=%ld, Orient:[%s], Closed:[%s], LastPVert:[%s], LastPos[%lf %lf %lf]"),
             _T("notNULL"), 
             lNumPolyEdges,
             m_eOrientation == SM_OT_SAME ? _T("SM_OT_SAME=OuterLoop") : _T("SM_OT_OPPOSITE=InnerLoop"),
             m_bClosed ? _T("TRUE") : _T("FALSE"),
             m_pLastEndPolyVertex ? _T("notNULL") : _T("NULL"),
             m_sLastEndPoint.x, m_sLastEndPoint.y, m_sLastEndPoint.z) ;
  smos_WriteBuffer(sBuff, sBuffForFile);

  // PolyLoop->PolyEdges
  for(ii=0;ii<sPolyEdges.GetSize();ii++)
    {
      smos_sprintf(sBuff,       _T("\n   PEdge %2ld:[0x%p] StPVert:[0x%p]=[%lf %lf %lf], OrigVertex[0x%p]"), 
                 ii,
                 sPolyEdges[ii],
                 sPolyEdges[ii]->GetStartPolyVertex(),
                 sPolyEdges[ii]->GetStartPoint().x,
                 sPolyEdges[ii]->GetStartPoint().y,
                 sPolyEdges[ii]->GetStartPoint().z,
                 sPolyEdges[ii]->GetStartPolyVertex()->GetOriginalVertex()) ;
      smos_sprintf(sBuffForFile, _T("\n   PEdge %2ld:[%s] StPVert:[%s]=[%lf %lf %lf], OrigVertex[%s]"), 
                 ii,
                 sPolyEdges[ii] ? _T("notNULL") : _T("NULL"),
                 sPolyEdges[ii]->GetStartPolyVertex() ? _T("notNULL") : _T("NULL"),
                 sPolyEdges[ii]->GetStartPoint().x,
                 sPolyEdges[ii]->GetStartPoint().y,
                 sPolyEdges[ii]->GetStartPoint().z,
                 sPolyEdges[ii]->GetStartPolyVertex()->GetOriginalVertex() ? _T("notNULL") : _T("NULL")) ;  
      smos_WriteBuffer(sBuff, sBuffForFile);
    }
} // end SmPolyLoop::Dump

