/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyFace::Dump(void) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  // locals
  SM_PTR_ARRAY(sPolyLoops, SmPolyLoop,  16) ;         
  SM_PTR_ARRAY(sPolyEdges, SmPolyEdge, 256) ;         
  GetPolyLoops(sPolyLoops) ;
  GetPolyEdges(sPolyEdges) ;
  ULONG        lNumPolyLoops = sPolyLoops.GetSize() ;
  ULONG        lNumPolyEdges = sPolyEdges.GetSize() ;

  // face header
  smos_sprintf(sBuff,        _T("\nPolyFace:[0x%p] = NumLoops[%ld], NumEdges[%ld], OrigFace:[0x%p], CFaceOwner:[0x%p], Tol[%16.16lf]"),
             this,
             lNumPolyLoops,
             lNumPolyEdges,
             m_pOriginalFace,
             m_pCPolyFace,
             (double)m_sZoneTol3d);
  smos_sprintf(sBuffForFile, _T("\nPolyFace:[%s] = NumLoops[%ld], NumEdges[%ld], OrigFace:[%s], CFaceOwner:[%s], Tol[%16.16lf]"),
             _T("notNULL"),
             lNumPolyLoops,
             lNumPolyEdges,
             m_pOriginalFace ? _T("notNULL") : _T("NULL"),
             m_pCPolyFace ? _T("notNULL") : _T("NULL"),
             (double)m_sZoneTol3d);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // Geometry - normal, deviation - can be uninitialized
  if(m_vNormal.IsInitialized()) { smos_sprintf(sBuff,       _T("\n  Normal:[%lf %lf %lf], "), 
                                             m_vNormal.x, m_vNormal.y, m_vNormal.z);
                                  smos_WriteBuffer(sBuff);
                                }
  else                          { smos_WriteBuffer(_T("\n  Normal:[uninit], ")); }

  if(m_dMaxDeviation != -SM_BIG_DOUBLE) { smos_sprintf(sBuff,       _T("MaxVertexToPlaneDeviation[%16.16lf]"), m_dMaxDeviation);
                                          smos_WriteBuffer(sBuff);
                                        }
  else                                  { smos_WriteBuffer(_T("MaxVertexToPlaneDeviation[uninit]")); }

  if(!m_vNormal.IsInitialized() || m_dMaxDeviation == -SM_BIG_DOUBLE)
    { 
      smos_WriteBuffer(_T(" - uninit OK: Set with next SmPolyFace::GetNormal() call"));
    }

  // geometry - sphere center, radius - can be uninitialized
  if(m_vSphereCenter.IsInitialized())
    {
      smos_sprintf(sBuff,       _T("\n  Center:[%lf %lf %lf], SphereRadius[%16.16lf]"),
                 m_vSphereCenter.x, m_vSphereCenter.y, m_vSphereCenter.z,
                 m_dSphereRadius); 
      smos_WriteBuffer(sBuff);
    }
  else 
    { 
      smos_WriteBuffer(_T("\n  Center:[uninit], SphereRadius[uninit] - uninit OK: Set with next SmPolyFace::ComputeSphereBound() call"));
    }

  // temp values
  smos_sprintf(sBuff,       _T("\n  IndxVal[%ld], UserLong1[%ld], UserLong2[%ld], SmoothGroup[%ld]"),
             m_lIndexValue,
             m_lUserLong1,
             m_lUserLong2,
             m_lSmoothGroup);
  smos_WriteBuffer(sBuff);

  // all done
  smos_sprintf(sBuff,        _T("\nEND Dump() PolyFace:[0x%p]"), this);
  smos_sprintf(sBuffForFile, _T("\nEND Dump() PolyFace:[%s]"),   _T("notNULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmPolyFace::Dump

