/*******************************************************************//**
PURPOSE:

NOTES: 1. skips checks when IsMarked(SM_MT_MARKASSERT) else marks this object.
       2. if(eWalkTree == SM_WALK) call AssertValid on every PolyShell.

RETURNS ---  TRUE  = OK
             FALSE = Problem
  Does not cascade Asserts from other AssertValid() calls.
***********************************************************************/
SmBoolean SmPolyRegion::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL] 
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests, 
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests 
                                    //      default:[SM_LEVEL_0] 
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK] 
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  // init rtn value
  SmBoolean bRtn = TRUE ; 

  // skip already marked objects - set this mark
  if(IsMarked(SM_MT_MARKASSERT))
    {
      return(bRtn) ; 
    }
  ((SmPolyRegion*)this)->Mark(SM_MT_MARKASSERT) ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmOwningTopology::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests) 
           : TRUE ) ; 

  // SmPolyRegion checks
  // There's really nothing here other than SmOwningTopology.

  // PolyRegion back pointers
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, this->GetNext()->GetLast() == this, _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, this->GetLast()->GetNext() == this, _T("") ) ;

  // Pass the call down.
  if( m_pList != NULL )
    {
      SmTopology *pTgt = m_pList;
      do
        {
          SmPolyShell *pShell = SM_CAST_PTR( SmPolyShell, pTgt );
          if( pShell == NULL ) 
               { bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (FALSE), _T("") ) ; }
          else { if(eWalkTree == SM_WALK) { bRtn &= pShell->AssertValid(pAList, eTestLevel, eWalkTree); } 
               }

          pTgt = pTgt->GetNext();

        } while ( pTgt != m_pList );
    }

  // all done
  // SM_ASSERT(bRtn) ;

  return(bRtn) ;

} // end SmPolyRegion::AssertValid

