/*******************************************************************//**
PURPOSE:
NOTES:
***********************************************************************/
SmBoolean SmPolyRegion::IsKindOf( SM_TYPE t ) const
{
  return ((SmPolyRegion_TYPE == t) ? TRUE : SmOwningTopology::IsKindOf( (t) ));
}

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyRegion::Dump(void) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  // locals
  ULONG ii ;
  SM_PTR_ARRAY (sPolyShells,     SmPolyShell,  16) ;         
  SM_PTR_ARRAY (sPolyShellFaces, SmPolyFace,  256) ; 
  GetPolyShells(sPolyShells) ;
  ULONG         lNumPolyShells = sPolyShells.GetSize() ;
  ULONG         lNumPolyFaces = 0 ;
  
  // for every Shell
  for(ii=0;ii<lNumPolyShells;ii++)
    {
      SmPolyShell * pPolyShell = sPolyShells[ii] ;
      pPolyShell->GetPolyFaces(sPolyShellFaces) ;

      lNumPolyFaces += sPolyShellFaces.GetSize() ;
    }

  // PolyRegion header
  smos_sprintf(sBuff,        _T("\nPolyRegion:[0x%p] = NumPolyShells[%ld], NumPolyFaces[%ld]"),
             this,
             lNumPolyShells,
             lNumPolyFaces);
  smos_sprintf(sBuffForFile, _T("\nPolyRegion:[%s] = NumPolyShells[%ld], NumPolyFaces[%ld]"),
             _T("NotNULL"),
             lNumPolyShells,
             lNumPolyFaces);
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmPolyRegion::Dump

/*******************************************************************//**
PURPOSE: Check a PolyBrep for coincident topology.

NOTES: 1. Returns TRUE when no coincident topology is found, else return FALSE
       2. Optionally called from AssertValid().
***********************************************************************/
SmBoolean SmPolyBrep::GetCoincidentTopology
 (double dTol,
  SmTArray< SmTopology * > & rObjs1, // out: associated lists of coincident entities
  SmTArray< SmTopology * > & rObjs2) 
 const
{
  rObjs1.ReSet();
  rObjs2.ReSet();

  // Check vertices.
  SM_PTR_ARRAY(sVerts, SmPolyVertex, 512) ; // SmTArray<SmPolyVertex*>  

  this->GetPolyVertices( sVerts );
  SmPoint3d sPos1, sPos2;
  double dDist, dParam;
  double dTolSq = dTol*dTol;

  ULONG ii, jj, lNumVerts = sVerts.GetSize();
  for(ii=0;ii<lNumVerts;ii++)
  {
      sPos1 = sVerts[ii]->GetPoint();
      for(jj=ii+1;jj<lNumVerts;jj++)
      {
          sPos2 = sVerts[jj]->GetPoint();

          if( sPos1.DistanceBetweenSquared( sPos2 ) < dTolSq )
          {
              rObjs1.Add( (SmTopology *) sVerts[ii] );
              rObjs2.Add( (SmTopology *) sVerts[jj] );
          }
      } // end inner loop on all PolyVertices
  } // end outer loop on all PolyVertices

  // Check edges.
  SmPoint3d  sP1, sP2;
  SmVector3d sV1, sV2;
  SM_PTR_ARRAY(sEdges, SmPolyEdge, 512) ; // SmTArray<SmPolyEdge*>  

  this->GetPolyEdges( sEdges );
  ULONG lNumEdges = sEdges.GetSize();
  for(ii=0;ii<lNumEdges;ii++)
  {
      SmPolyEdge *pE1 = sEdges[ii];
      pE1->GetLine( sP1, sV1 );

      // Don't check zero-length lines.
      // We could reconsider this decision if desired.
      double dLen1 = sV1.Length();
      if( dLen1 < dTol )
        { continue; }
      sV1 /= dLen1;

      for(jj=ii+1;jj<lNumEdges;jj++)
      {
          SmPolyEdge *pE2 = sEdges[jj];

          // Don't check radials.
          if( pE2->IsRadialPartnerOf( pE1 ) )
            { continue; }

          pE2->GetLine( sP2, sV2 );
          double dLen2 = sV2.Length();
          if( dLen2 < dTol )
            { continue; }
          sV2 /= dLen2;

          // Parallel?
          double dDot = sV1.Dot( sV2 );
          if( smos_Fabs( dDot ) < 0.99985 ) // about 1 degree
            { continue; }

          // Check all four end points.
          // If at least two are on the other edge within tolerance,
          // and the two are not the same point (don't flag end-to-end case),
          // call it coincident.
          SmPoint3d sEnd1 = sP1 + dLen1 * sV1;
          SmPoint3d sEnd2 = sP2 + dLen2 * sV2;
          int iNumHits = 0;

          // If off the end, this routine returns distance to end:
          if( smgu_IsPointOnSegment( sP1, sEnd1, sP2, dTol, dDist, dParam ) )
          {
              iNumHits++;
              sPos1 = sP1 + dParam * dLen1 * sV1;
          }

          if( smgu_IsPointOnSegment( sP1, sEnd1, sEnd2, dTol, dDist, dParam ) )
          {
              if( iNumHits == 0 )
              {
                  iNumHits++;
                  sPos1 = sP1 + dParam * dLen1 * sV1;
              }
              else
              {
                  sPos2 = sP1 + dParam * dLen1 * sV1;
                  if( sPos2.DistanceBetween( sPos1 ) > dTol )
                    { iNumHits++; }
              }
          }

          if( iNumHits < 2 )
          {
              if( smgu_IsPointOnSegment( sP2, sEnd2, sP1, dTol, dDist, dParam ) )
              {
                  if( iNumHits == 0 )
                  {
                      iNumHits++;
                      sPos1 = sP2 + dParam * dLen2 * sV2;
                  }
                  else
                  {
                      sPos2 = sP2 + dParam * dLen2 * sV2;
                      if( sPos2.DistanceBetween( sPos1 ) > dTol )
                        { iNumHits++; }
                  }
              }

          }
          if( iNumHits < 2 )
          {
              if( smgu_IsPointOnSegment( sP2, sEnd2, sEnd1, dTol, dDist, dParam ) )
              {
                  if( iNumHits == 0 )
                  {
                      iNumHits++;
                      sPos1 = sP2 + dParam * dLen2 * sV2;
                  }
                  else
                  {
                      sPos2 = sP2 + dParam * dLen2 * sV2;
                      if( sPos2.DistanceBetween( sPos1 ) > dTol )
                        { iNumHits++; }
                  }
              }
          }

          if( iNumHits >= 2 )
          {
              rObjs1.Add( (SmTopology *) pE1 );
              rObjs2.Add( (SmTopology *) pE2 );
          }
      } // end inner loop on all PolyEdges
  } // end outer loop on all PolyEdges

  // Check faces.
  // First check geometrically the same plane,
  // then check for overlap.

  SM_PTR_ARRAY(sFaces,  SmPolyFace, 512); // SmTArray<SmPolyFace*>  
  SM_PTR_ARRAY(sLoops1, SmPolyLoop,  16); // SmTArray<SmPolyLoop*>  
  SM_PTR_ARRAY(sLoops2, SmPolyLoop,  16); // SmTArray<SmPolyLoop*>  

  this->GetPolyFaces( sFaces );
  ULONG lNumFaces = sFaces.GetSize();

  // And we'll do boxing tests to rule out most.
  SmExtent3d sBox1, sBox2;

  for(ii=0;ii<lNumFaces;ii++)
  {
      SmPolyFace *pF1 = sFaces[ii];

      pF1->GetPolyLoops( sLoops1 );
      ULONG kk, lNumLoops1 = sLoops1.GetSize();

      for(kk=0;kk<lNumLoops1;kk++)
      {
          SmPolyLoop* pL1 = sLoops1[kk];

          pL1->CalculateBoundingBox( sBox1 );


          for(jj=ii+1;jj<lNumFaces;jj++)
          {
              SmPolyFace *pF2 = sFaces[jj];

              // Do the geometry test here.
              double dDot = pF1->GetNormal().Dot( pF2->GetNormal() );
              if( smos_Fabs( dDot ) < 0.99985 ) // about 1 degree
                { continue; }

              // Ok, check overlap of loops.
              pF2->GetPolyLoops( sLoops2 );
              ULONG ll, lNumLoops2 = sLoops2.GetSize();

              for(ll=0;ll<lNumLoops2;ll++)
              {
                  SmPolyLoop *pL2 = sLoops2[ll];

                  pL2->CalculateBoundingBox( sBox2 );

                  if( sBox1.AreDisjoint( sBox2, dTol ) )
                    { continue; }

                  SmPolyContainmentType eInside;
                  SmStatus eStat = pL1->OverlapsPolyLoop( pL2, eInside, dTol );
                  if( eStat != SM_SUCCESS )
                    { continue; }

                  if( eInside == SM_PCT_INSIDE )
                    {
                      rObjs1.Add( (SmTopology *) pF1 );
                      rObjs2.Add( (SmTopology *) pF2 );
                    }
                } // end inner loop on all PolyLoops in the PolyFace
            } // end inner loop on all PolyFaces

        } // end outer loop on all PolyLoops in the PolyFace
    } // end outer loop on all PolyFaces

  // all done
  return( 0 == rObjs1.GetSize()) ;
  
} // end SmPolyBrep::CheckCoincidentTopology

