//            double dEndParam2   = sLessThanData.m_sDirVec.Dot(sCommonPolyEdges2[ii]->GetEndPoint()) ;
//            sMaxParams[ii]      = smos_Max(dStartParam2, dEndParam2) ;
//          }
//      }
//  #endif // SM_DEBUG_CODE
//  
//        // for every CommonPolyEdge - look for intersecting pairs
//        ULONG iEndIndx=0 ;
//        double dThisLength, dMaxLength = 0.0 ;
//  
//        // For every PolyEdge - find max length
//        for(jj=0;jj<sCommonPolyEdges1.GetSize()-1;jj++)
//          {
//            dThisLength = sCommonPolyEdges1[jj]->GetVec().Dot(sLessThanData.m_sDirVec) ;
//            if(dThisLength > dMaxLength) { dMaxLength = dThisLength ; }
//          }
//    
//        // For every PolyEdge - running in MinParam order
