/*******************************************************************//**
PURPOSE: AssertValid() Test reporting static labels
***********************************************************************/
SmAssertReportLabel sAssertPolyBrep_list[] =
{
/*  0 */ {SM_AT_POINTER,     _T("Context"),                     _T("m_pPolyVertexListHead shares the same context") },
/*  1 */ {SM_AT_POINTER,     _T("Context"),                     _T("m_pCPolyFaceListHead shares the same context") },
/*  2 */ {SM_AT_POINTER,     _T("Null"),                        _T("pRegion is non-NULL") },
/*  3 */ {SM_AT_POINTER,     _T("Null"),                        _T("NULL PolyVertexPtr in PolyVertex list") },
/*  4 */ {SM_AT_POINTER,     _T("Null"),                        _T("NULL CPolyFace in CPolyFace list") },
/*  5 */ {SM_AT_COINCIDENCE, _T("Coincidence"),                 _T("Coincident Topology") },
/*  6 */ {SM_AT_GEOMETRIC,   _T("Uniform 2d/3d"),               _T("Mixed 2d and 3d PolyVertex position spaces") },
/*  7 */ {SM_AT_COINCIDENCE, _T("Coincident PolyVerts"),        _T("Coincidence PolyVertices") },
/*  8 */ {SM_AT_GEOMETRIC,   _T("Intersecting PolyEdges"),      _T("PolyEdges intersect one another") },
/*  9 */ {SM_AT_TOPOLOGICAL, _T("Vertex List duplicate entry"), _T("PolyVertex listed multiple times on m_pVertexListHead") } 
} ;

/*******************************************************************//**
PURPOSE:

NOTES: when eWalkTree == SM_WALK, calls NewMark(SM_MT_MARKASSERT) 
       then walks topology graph calling AssertValid on every Topology object

RETURNS ---  TRUE  = OK
             FALSE = Problem
  Does not cascade Asserts from other AssertValid() calls.
***********************************************************************/
SmBoolean SmPolyBrep::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL] 
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests, 
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests 
                                    //      default:[SM_LEVEL_0] 
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK] 
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  ULONG ii ;

  // init rtn value
  SmBoolean bOk, bRtn = TRUE ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmSAGObject::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests) 
           : TRUE ) ; 

  // Context checks - all PolyVertices and CPolyFaces have the same Context
  if( m_pPolyVertexListHead != NULL ) 
    { 
      bOk = ( m_pPolyVertexListHead->GetContext() == this->GetContext() ); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (bOk), _T("") ) ;
    }
  if( m_pCPolyFaceListHead  != NULL ) 
    { 
      bOk = ( m_pCPolyFaceListHead ->GetContext() == this->GetContext() ); 
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, (bOk), _T("") ) ;
    }

  // coincident PolyVertices - might be O(N*logN) depends on the time to do the sort 
  SmTArray<SmPolyVertex *> sPolyVertices1, sPolyVertices2 ;
  GetCoincidentPolyVertices(sPolyVertices1, sPolyVertices2) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(7, SM_LEVEL_0, (sPolyVertices1.GetSize() == 0), _T("") ) ;

 //  // self intersecting edges - O(N**2) too expensive to run
 //  SmTArray<SmPolyEdge *> sPolyEdges1, sPolyEdges2 ;
 //  GetIntersectingPolyEdges(sPolyEdges1, sPolyEdges2) ;    // note: increments unlocked mark value
 //  bRtn &= SM_ASSERT_BOOLEAN_REPORT(8, SM_LEVEL_0, (sPolyEdges1.GetSize() == 0), _T("") ) ;

  // start AssertValid topology graph walk 
  if(eWalkTree == SM_WALK)
    {
      SmNewMarkAndLock sMarkLock(GetContext(), SM_MT_MARKASSERT) ;   // increment and lock SM_MT_MARKASSERT
      SmMarkType eMarkType = sMarkLock.GetMarkType() ;               // fetch the mark that was locked

      ((SmPolyBrep*)this)->Mark(eMarkType) ;
    } 
  
  // for every PolyRegion call AssertValid
  if( m_pList != NULL )
    {
      SM_PTR_ARRAY  (sPolyRegions, SmPolyRegion, 16) ;
      GetPolyRegions(sPolyRegions) ;
      for(ii=0;ii<sPolyRegions.GetSize();ii++)
        {
          if(sPolyRegions[ii]) { // walk topology graph
                                 if(eWalkTree == SM_WALK) { bRtn &= sPolyRegions[ii]->AssertValid(pAList, eTestLevel, eWalkTree); }
                               }
          else                 { // PolyRegion ptr is NULL
                                 bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (FALSE), _T("") ) ; 
                               }
        } // end iter every PolyRegion

    } // end PolyRegion existence check

  // PolyVertex list check - all PolyVertices in the same space (2d or 3d)
  //                       - no NULL pointers on the PolyVertex list
  if( m_pPolyVertexListHead != NULL  &&  m_pPolyVertexListHead->GetList() != NULL )
    {
      SM_PTR_ARRAY   (sPolyVertices, SmPolyVertex, 512) ;
      GetPolyVertices(sPolyVertices) ;

      // all PolyVertices must be in same 2d or 3d space
      SmBoolean   bIs2d = Is2d() ;
      SmBoolean   b2dOK = TRUE ; 
      for(ii=0;ii<sPolyVertices.GetSize();ii++)
        {
          if(sPolyVertices[ii]) { // check Vertex for common space - only report 1st problem
                                  bRtn &= SM_ASSERT_BOOLEAN_REPORT(6, SM_LEVEL_0, b2dOK && bIs2d == sPolyVertices[ii]->Is2d(), _T("") ) ;
                                  if( b2dOK && bIs2d != sPolyVertices[ii]->Is2d())
                                    { b2dOK = FALSE ; }
                                }
          else                  { // PolyVertex ptr is NULL
                                  bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, (FALSE), _T("") ) ; 
                                }
        }
    } // end m_pVertexListHead existence check

  //  PolyCFace list Check - Call AssertValid on all CPolyFaces
  //                       - No NULL pointers on the CPolyFace list
  if( m_pCPolyFaceListHead != NULL  &&  m_pCPolyFaceListHead->GetList() != NULL )
    {
      SM_PTR_ARRAY  (sCPolyFaces, SmCPolyFace, 128) ;
      GetCPolyFaces(sCPolyFaces) ;
      for(ii=0;ii<sCPolyFaces.GetSize();ii++)
        {
          if(sCPolyFaces[ii]) { // Composite faces are not hit on the topology graph walk - check them here
                                if(eWalkTree == SM_WALK) { bRtn &= sCPolyFaces[ii]->AssertValid(pAList, eTestLevel, eWalkTree); }
                              }
          else                { // CPolyFace ptr is NULL
                                bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, (FALSE), _T("") ) ; 
                              }
        } // end iter every PolyCFace
    } // end PolyCFace existence check

  // check for Coincident topology objects
  //#define cbiCoinc
  #ifdef cbiCoinc // This is usually extremely expensive.
    {
      SM_PTR_ARRAY(sCoinc1, SmTopology, 64); // SmTArray<SmTopology*>  
      SM_PTR_ARRAY(sCoinc2, SmTopology, 64); // SmTArray<SmTopology*>  

      GetCoincidentTopology( GetTolerance(), sCoinc1, sCoinc2 );
      SmBoolean bCoinc = sCoinc1.GetSize() > 0 ;

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe=FALSE;
      if( bDebugMe ) 
        {
          ULONG lNumCoinc = sCoinc1.GetSize();
          for(ii=0;ii<lNumCoinc;ii++)
            {
              SmTopology *pTopo1 = sCoinc1[ii];
              SmTopology *pTopo2 = sCoinc2[ii];

              pTopo1->Dump();
              pTopo2->Dump();

              SmPolyVertex *pVert1 = SM_CAST_PTR( SmPolyVertex, pTopo1 );
              SmPolyEdge   *pEdge1 = SM_CAST_PTR( SmPolyEdge,   pTopo1 );
              SmPolyFace   *pFace1 = SM_CAST_PTR( SmPolyFace,   pTopo1 );

              sm_GraphicsLoop();
              smgfx_SetLook( 3,5, 1,0,0 ); if(pVert1) pVert1->Draw();   sm_GraphicsLoop(); 
              smgfx_SetLook( 3,5, 1,0,0 ); if(pEdge1) pEdge1->Draw();   sm_GraphicsLoop(); 
              smgfx_SetLook( 3,5, 1,0,0 ); if(pEdge1) pEdge1->Draw3D(); sm_GraphicsLoop(); 
              smgfx_SetLook( 3,5, 1,0,0 ); if(pFace1) pFace1->Draw();   sm_GraphicsLoop(); 
              sm_GraphicsLoop();
            }
        }
#endif // SM_DEBUG_CODE

      bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, (bCoinc==FALSE), _T("") ) ;
    }
    #endif

  // GWC_NEEDS_WORK VERY_SLOW_COINCIDENT_VERTEX_ASSERT_REPLACE_WITH_SmHealData::Cache_CoinVertex() like algorithm
  
  // check for duplicate entries on the Vertex List - this is O(N**2)
  SM_PTR_ARRAY(sPolyVertices,      SmPolyVertex, 512) ;
  SM_PTR_ARRAY(sDuplicateVertices, SmPolyVertex,  16) ;
  GetPolyVertices(sPolyVertices) ;
  sPolyVertices.GetDuplicates(sDuplicateVertices) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(9, SM_LEVEL_2, (sDuplicateVertices.GetSize() == 0), _T("") ) ;

  // all done
  // SM_ASSERT(bRtn) ;
  return(bRtn) ;

} // end SmPolyBrep::AssertValid

