// Dump preceded by a one line message
/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyBrep::Dump(TCHAR * message) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE];
  smos_sprintf(sBuff,_T("\n%s"), message);
  smos_WriteBuffer(sBuff);
  this->Dump();
}

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyBrep::Dump(ULONG ii) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE];
  smos_sprintf(sBuff,_T("\n%ld "), ii);
  smos_WriteBuffer(sBuff);
  this->Dump();
}

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyBrep::Dump(void) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  ULONG ii, jj ;
  ULONG lLamina = 0, lManifold = 0, lSpine = 0;
  SM_PTR_ARRAY(sPolyRegions,     SmPolyRegion,  16); // SmTArray<SmPolyRegion*>  
  SM_PTR_ARRAY(sPolyShells,      SmPolyShell ,  16); // SmTArray<SmPolyShell *>
  SM_PTR_ARRAY(sPolyFaces,       SmPolyFace  , 512); // SmTArray<SmPolyFace  *>  
  SM_PTR_ARRAY(sPolyEdges,       SmPolyEdge  , 512); // SmTArray<SmPolyEdge  *>  
  SM_PTR_ARRAY(sPolyVertices,    SmPolyVertex, 512); // SmTArray<SmPolyVertex*>  
  SM_PTR_ARRAY(sPolyVertexEdges, SmPolyEdge,    16); // SmTArray<SmPolyEdge  *>
  SM_PTR_ARRAY(sPolyFaceLoops,   SmPolyLoop,    16); // SmTArray<SmPolyEdge  *>
  SM_PTR_ARRAY(sPolyLoopEdges,   SmPolyEdge,    16); // SmTArray<SmPolyEdge  *>
    
  GetPolyRegions (sPolyRegions);
  GetPolyShells  (sPolyShells);
  GetPolyFaces   (sPolyFaces);
  GetPolyEdges   (sPolyEdges);
  GetPolyVertices(sPolyVertices);

  // count PolyObjects
  ULONG lNumPolyRegions       = sPolyRegions.GetSize() ;
  ULONG lNumPolyShells        = sPolyShells.GetSize() ;
  ULONG lNumPolyFaces         = sPolyFaces.GetSize() ;
  ULONG lNumPolyEdges         = sPolyEdges.GetSize() ;
  ULONG lNumPolyVertices      = sPolyVertices.GetSize() ;
  ULONG lNumPolyLoops         = 0 ;
  ULONG lNumOpenPolyLoops     = 0 ;
  ULONG lNumPolyEdgesAtVertex, lAvgPolyEdgesAtVertex = 0, lMaxPolyEdgesAtVertex = 0, lMinPolyEdgesAtVertex = SM_UNDEF_ULONG ; 
  ULONG lNumPolyLoopsInFace,   lAvgPolyLoopsInFace   = 0, lMaxPolyLoopsInFace   = 0, lMinPolyLoopsInFace   = SM_UNDEF_ULONG ; 
  ULONG lNumPolyEdgesInLoop,   lAvgPolyEdgesInLoop   = 0, lMaxPolyEdgesInLoop   = 0, lMinPolyEdgesInLoop   = SM_UNDEF_ULONG ; 
      
  // BBox
  SmExtent3d sBBox ;
  CalculateBoundingBox(sBBox) ;

  // count edge types
  for(ii=0;ii<sPolyEdges.GetSize();ii++)
    {
      if(sPolyEdges[ii]->IsLamina())        { lLamina++ ; }
      else if(sPolyEdges[ii]->IsManifold()) { lManifold++ ; }
      else                                  { lSpine++ ; }
    }

  // get PolyVertex edge counts
  for(ii=0;ii<lNumPolyVertices;ii++)
    {
      SmPolyVertex *pPolyVertex = sPolyVertices[ii] ;
      pPolyVertex->GetPolyEdges(sPolyVertexEdges) ;

      // Count, Avg, Max PolyEdges at Vertex
      lNumPolyEdgesAtVertex  = sPolyVertexEdges.GetSize() ;
      lAvgPolyEdgesAtVertex += lNumPolyEdgesAtVertex ;
      if(lMaxPolyEdgesAtVertex < lNumPolyEdgesAtVertex)  { lMaxPolyEdgesAtVertex = lNumPolyEdgesAtVertex ; }
      if(lMinPolyEdgesAtVertex > lNumPolyEdgesAtVertex)  { lMinPolyEdgesAtVertex = lNumPolyEdgesAtVertex ; }

    } // end iter ii, every PolyVertex looking at EdgeAt count

  // get PolyFace Loop and Edge counts
  for(ii=0;ii<lNumPolyFaces;ii++)
    {
      SmPolyFace *pPolyFace = sPolyFaces[ii] ;
      pPolyFace->GetPolyLoops(sPolyFaceLoops) ;

      // Count, Avg, Max PolyLoops on Face
      lNumPolyLoopsInFace  = sPolyFaceLoops.GetSize() ;
      lAvgPolyLoopsInFace += lNumPolyLoopsInFace ;
      if(lMaxPolyLoopsInFace < lNumPolyLoopsInFace)  { lMaxPolyLoopsInFace = lNumPolyLoopsInFace ; }
      if(lMinPolyLoopsInFace > lNumPolyLoopsInFace)  { lMinPolyLoopsInFace = lNumPolyLoopsInFace ; }

      // Get PolyLoop edge counts
      for(jj=0;jj<lNumPolyLoopsInFace;jj++)
        {
          SmPolyLoop *pPolyFaceLoop = sPolyFaceLoops[jj] ;
          pPolyFaceLoop->GetPolyEdges(sPolyLoopEdges) ;

          // count openPolyLoops
          if(!pPolyFaceLoop->IsClosed()) { lNumOpenPolyLoops += 1 ; }

          // Count, Avg, Max PolyEdges in loop
          lNumPolyEdgesInLoop  = sPolyLoopEdges.GetSize() ;
          lAvgPolyEdgesInLoop += lNumPolyEdgesInLoop ;
          if(lMaxPolyEdgesInLoop < lNumPolyEdgesInLoop) { lMaxPolyEdgesInLoop = lNumPolyEdgesInLoop ; }
          if(lMinPolyEdgesInLoop > lNumPolyEdgesInLoop) { lMinPolyEdgesInLoop = lNumPolyEdgesInLoop ; }

        } // end iter jj, every PolyFaceLoop for PolyEdge counts
    } // end iter ii, every PolyFace for PolyLoop counts

  // turn totals into averages
  lNumPolyLoops = lAvgPolyLoopsInFace ;

  if(lNumPolyVertices > 0) { lAvgPolyEdgesAtVertex /= lNumPolyVertices ; }
  if(lNumPolyFaces    > 0) { lAvgPolyLoopsInFace   /= lNumPolyFaces ; }
  if(lNumPolyLoops    > 0) { lAvgPolyEdgesInLoop   /= lNumPolyLoops ; }

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nMANIFOLD PolyBrep:"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nNonMANIFOLD PolyBrep:"));
  smos_WriteBuffer(sBuff);

  // brep header 
  smos_sprintf(sBuff,         _T("[0x%p], Regions = %ld, Shells = %ld, Faces = %ld, Loops = %ld:[open = %ld], Edges = %ld, Verts = %ld"),
             this,
             lNumPolyRegions,
             lNumPolyShells,
             lNumPolyFaces,
             lNumPolyLoops, lNumOpenPolyLoops,
             lNumPolyEdges,
             lNumPolyVertices);
  smos_sprintf(sBuffForFile,  _T("[%s], Regions = %ld, Shells = %ld, Faces = %ld, Loops = %ld:[open = %ld], Edges = %ld, Verts = %ld"),
             _T("notNULL"),
             lNumPolyRegions,
             lNumPolyShells,
             lNumPolyFaces,
             lNumPolyLoops, lNumOpenPolyLoops,
             lNumPolyEdges,
             lNumPolyVertices);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // Edge types
  smos_sprintf(sBuff,         _T("\n          Edges = %ld :[Lamina = %ld, Manifold = %ld, Spine = %ld], Tol:[%16.16lf]"),
             lNumPolyEdges, lLamina, lManifold, lSpine, 
             (double)m_sZoneTol3d);
  smos_WriteBuffer(sBuff);

  // bounding box
  sBBox.Dump() ;

  // connect and type statistics
  smos_sprintf(sBuff,         _T("\n          Avg Num EdgesAtVertex = %ld :[Max = %ld, Min = %ld]; nLamina = %ld"),
             lAvgPolyEdgesAtVertex, lMaxPolyEdgesAtVertex, lMinPolyEdgesAtVertex,         
             lLamina);                                                                    
  smos_WriteBuffer(sBuff);                                                                
                                                                                          
  smos_sprintf(sBuff,         _T("\n          Avg Num LoopsInFace   = %ld :[Max = %ld, Min = %ld]; nManifold = %ld"),
             lAvgPolyLoopsInFace,   lMaxPolyLoopsInFace,   lMinPolyLoopsInFace,           
             lManifold);                                                                  
  smos_WriteBuffer(sBuff);                                                                
                                                                                          
  smos_sprintf(sBuff,         _T("\n          Avg Num EdgesinLoop   = %ld :[Max = %ld, Min = %ld]; nSpine = %ld"),
             lAvgPolyEdgesInLoop,   lMaxPolyEdgesInLoop,   lMinPolyEdgesInLoop,         
             lSpine);
  smos_WriteBuffer(sBuff);

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nEND Dump() MANIFOLD PolyBrep:"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nEND Dump() NonMANIFOLD PolyBrep:"));
  smos_WriteBuffer(sBuff);

  // brep header 
  smos_sprintf(sBuff,         _T("[0x%p]"), this);
  smos_sprintf(sBuffForFile,  _T("[%s]"),   _T("notNULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmPolyBrep::Dump

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyBrep::DumpPolyFaces
  (ULONG lSampleFrequency, // in : SampleFrequence, eg:[1] = print all faces, [10] = Print one-in-10 faces, default:[10]
   SmBoolean bWithAttribs) // in : TRUE = Only Dump objs with attributs, FALSE=Dump all objs, default:[TRUE]
  const                    
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  ULONG ii, jj ;
  ULONG lLamina = 0, lManifold = 0, lSpine = 0;
  SM_PTR_ARRAY(sPolyFaces,          SmPolyFace  , 512); // SmTArray<SmPolyFace  *>  
  SM_PTR_ARRAY(sPolyFaceLoops,      SmPolyLoop,    16); // SmTArray<SmPolyLoop  *>
  SM_PTR_ARRAY(sPolyFaceEdges,      SmPolyEdge,    16); // SmTArray<SmPolyEdge  *>
  SM_PTR_ARRAY(sPolyEdges,          SmPolyEdge  , 512); // SmTArray<SmPolyEdge  *> 
  SM_PTR_ARRAY(sPolyFaceAttributes, SmAttribute,  512); // SmTArray<SmAttribute *>
    
  // get and count PolyFacess
  GetPolyFaces(sPolyFaces);
  ULONG lNumPolyFaces = sPolyFaces.GetSize() ;
  ULONG lNumPolyEdges = sPolyEdges.GetSize() ;

  // count edge types
  for(ii=0;ii<sPolyEdges.GetSize();ii++)
    {
      if(sPolyEdges[ii]->IsLamina())        { lLamina++ ; }
      else if(sPolyEdges[ii]->IsManifold()) { lManifold++ ; }
      else                                  { lSpine++ ; }
    }

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nMANIFOLD PolyBrep->DumpPolyFaces():"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nNonMANIFOLD PolyBrep->DumpPolyFaces():"));
  smos_WriteBuffer(sBuff);

  // PolyBrep header 
  smos_sprintf(sBuff,         _T("[0x%p], Faces = %ld"), this, lNumPolyFaces);
  smos_sprintf(sBuffForFile,  _T("[%s], Faces = %ld"), _T("notNULL"), lNumPolyFaces);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // faces
  for(ii=0;ii<lNumPolyFaces;ii+=lSampleFrequency)
    {
      SmPolyFace *pPolyFace = sPolyFaces[ii] ;
      pPolyFace->GetPolyLoops(sPolyFaceLoops) ;
      pPolyFace->GetPolyEdges(sPolyFaceEdges) ;
      pPolyFace->GetAttributes(sPolyFaceAttributes) ;
      // SmFace * pOrigFace = pPolyFace->GetOriginalFace() ;

      if(!bWithAttribs || sPolyFaceAttributes.GetSize() > 0)
        {
          // face report
          smos_sprintf(sBuff,         _T("\n  %ld: [0x%p], OrigFace:[0x%p], loops:[%ld], edges:[%ld], attribs:[%ld]"), 
                     ii,
                     pPolyFace, 
                     pPolyFace->GetOriginalFace(),
                     sPolyFaceLoops.GetSize(), 
                     sPolyFaceEdges.GetSize(), 
                     sPolyFaceAttributes.GetSize()) ;
          smos_WriteBuffer(sBuff);

          if(sPolyFaceAttributes.GetSize() > 0)
            {
              for(jj=0;jj<sPolyFaceAttributes.GetSize();jj++)
                {
                  smos_sprintf(sBuff, _T("\n    att:[%ld] = "), jj ) ;
                  smos_WriteBuffer(sBuff);
                  sPolyFaceAttributes[jj]->Dump() ;
                }
            }
        } // end dumping attribs
    } // end iter PolyFaces

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nEND DumpPolyFaces() MANIFOLD PolyBrep:"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nEND DumpPolyFaces() NonMANIFOLD PolyBrep:"));
  smos_WriteBuffer(sBuff);

  // brep header 
  smos_sprintf(sBuff,         _T("[0x%p]"), this);
  smos_sprintf(sBuffForFile,  _T("[%s]"),   _T("notNULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmPolyBrep::DumpPolyFaces

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyBrep::DumpPolyEdges
  (ULONG lSampleFrequency, // in : SampleFrequence, eg:[1] = print all faces, [10] = Print one-in-10 faces, default:[10]
   SmBoolean bWithAttribs) // in : TRUE = Only Dump objs with attributs, FALSE=Dump all objs, default:[TRUE]
  const                    
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  ULONG ii, jj ;
  ULONG lLamina = 0, lManifold = 0, lSpine = 0;
  SM_PTR_ARRAY(sPolyEdges,          SmPolyEdge  , 512); // SmTArray<SmPolyEdge  *>  
  SM_PTR_ARRAY(sPolyEdgeAttributes, SmAttribute,  512); // SmTArray<SmAttribute *>
    
  // get and count PolyEdgess
  GetPolyEdges(sPolyEdges);
  ULONG lNumPolyEdges = sPolyEdges.GetSize() ;

  // count edge types
  for(ii=0;ii<sPolyEdges.GetSize();ii++)
    {
      if(sPolyEdges[ii]->IsLamina())        { lLamina++ ; }
      else if(sPolyEdges[ii]->IsManifold()) { lManifold++ ; }
      else                                  { lSpine++ ; }
    }

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nMANIFOLD PolyBrep->DumpPolyEdges():"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nNonMANIFOLD PolyBrep->DumpPolyEdges():"));
  smos_WriteBuffer(sBuff);

  // PolyBrep header 
  smos_sprintf(sBuff,         _T("[0x%p], Edges = %ld"), this, lNumPolyEdges);
  smos_sprintf(sBuffForFile,  _T("[%s], Edges = %ld"), _T("notNULL"), lNumPolyEdges);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // Edges
  for(ii=0;ii<lNumPolyEdges;ii+=lSampleFrequency)
    {
      SmPolyEdge *pPolyEdge = sPolyEdges[ii] ;
      pPolyEdge->GetAttributes(sPolyEdgeAttributes) ;

      SmEdgeuse * pOrigEdgeuse = pPolyEdge->GetOriginalEdgeuse() ;

      // face report
      if(!bWithAttribs || sPolyEdgeAttributes.GetSize() > 0 || pOrigEdgeuse)
        {
          smos_sprintf(sBuff, _T("\n  %ld: [0x%p], OrigEdgeuse:[0x%p], EdgeType:[%s], attribs:[%ld]"), 
                     ii,
                     pPolyEdge, 
                     pOrigEdgeuse, 
                       pPolyEdge->IsLamina() ? _T("Lamina")
                     : pPolyEdge->IsManifold() ? _T("Manifold") : _T("Spine"), 
                     sPolyEdgeAttributes.GetSize()) ; 
          smos_WriteBuffer(sBuff);

          if(sPolyEdgeAttributes.GetSize() > 0)
            {
              for(jj=0;jj<sPolyEdgeAttributes.GetSize();jj++)
                {
                  smos_sprintf(sBuff, _T("\n    att:[%ld] = "), jj ) ;
                  smos_WriteBuffer(sBuff);
                  sPolyEdgeAttributes[jj]->Dump() ;
                }
            } // end dumping attribs
        }
    } // end iter PolyEdges

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nEND DumpPolyEdges() MANIFOLD PolyBrep:"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nEND DumpPolyEdges() NonMANIFOLD PolyBrep:"));
  smos_WriteBuffer(sBuff);

  // brep header 
  smos_sprintf(sBuff,         _T("[0x%p]"), this);
  smos_sprintf(sBuffForFile,  _T("[%s]"),   _T("notNULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmPolyBrep::DumpPolyEdges

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmPolyBrep::DumpPolyVertices
  (ULONG lSampleFrequency, // in : SampleFrequence, eg:[1] = print all faces, [10] = Print one-in-10 faces, default:[10]
   SmBoolean bWithAttribs) // in : TRUE = Only Dump objs with attributs, FALSE=Dump all objs, default:[TRUE]
  const                    
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];

  ULONG ii, jj ;
  ULONG lLamina = 0, lManifold = 0, lSpine = 0;
  SM_PTR_ARRAY(sPolyEdges,          SmPolyEdge   , 512); // SmTArray<SmPolyEdge  *>  
  SM_PTR_ARRAY(sPolyVertices,       SmPolyVertex , 512); // SmTArray<SmPolyVertex  *>
  SM_PTR_ARRAY(sPolyVertexEdges,    SmPolyEdge   ,  16); // SmTArray<SmPolyEdge*>  
  SM_PTR_ARRAY(sPolyVertexAttributes, SmAttribute, 512); // SmTArray<SmAttribute *>
    
  // get and count PolyEdges, PolyVertices
  GetPolyEdges(sPolyEdges);
  GetPolyVertices(sPolyVertices);
  ULONG lNumPolyEdges    = sPolyEdges.GetSize() ;
  ULONG lNumPolyVertices = sPolyVertices.GetSize() ;

  // count edge types
  for(ii=0;ii<sPolyEdges.GetSize();ii++)
    {
      if(sPolyEdges[ii]->IsLamina())        { lLamina++ ; }
      else if(sPolyEdges[ii]->IsManifold()) { lManifold++ ; }
      else                                  { lSpine++ ; }
    }

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nMANIFOLD PolyBrep->DumpPolyVertices():"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nNonMANIFOLD PolyBrep->DumpPolyVertices():"));
  smos_WriteBuffer(sBuff);

  // PolyBrep header 
  smos_sprintf(sBuff,         _T("[0x%p], Vertices = %ld"), this, lNumPolyVertices);
  smos_sprintf(sBuffForFile,  _T("[%s], Vertices = %ld"), _T("notNULL"), lNumPolyVertices);
  smos_WriteBuffer(sBuff, sBuffForFile);

  // Vertices
  for(ii=0;ii<lNumPolyVertices;ii+=lSampleFrequency)
    {
      SmPolyVertex *pPolyVertex = sPolyVertices[ii] ;
      pPolyVertex->GetPolyEdges( sPolyVertexEdges );
      pPolyVertex->GetAttributes(sPolyVertexAttributes) ;
      // SmVertex *pOrigVertex = pPolyVertex->GetOriginalVertex() ;

      // face report
      if(!bWithAttribs || sPolyVertexAttributes.GetSize() > 0)
        {
          smos_sprintf(sBuff,         _T("\n  %ld: [0x%p], OrigVertex:[0x%p], lNumEdges:[%ld], attribs:[%ld]"), 
                     ii,
                     pPolyVertex, 
                     pPolyVertex->GetOriginalVertex(),
                     sPolyVertexEdges.GetSize(), 
                     sPolyVertexAttributes.GetSize()) ;
          smos_WriteBuffer(sBuff);

          if(sPolyVertexAttributes.GetSize() > 0)
            {
              for(jj=0;jj<sPolyVertexAttributes.GetSize();jj++)
                {
                  smos_sprintf(sBuff, _T("\n    att:[%ld] = "), jj ) ;
                  smos_WriteBuffer(sBuff);
                  sPolyVertexAttributes[jj]->Dump() ;
                }
            } // end dumping attribs
        }
    } // end iter PolyEdges

  // output manifold/non_manifold status
  if (lNumPolyEdges == lManifold)
      smos_sprintf(sBuff,_T("%s"),_T("\nEND DumpPolyEdges() MANIFOLD PolyBrep:"));
  else
      smos_sprintf(sBuff,_T("%s"),_T("\nEND DumpPolyEdges() NonMANIFOLD PolyBrep:"));
  smos_WriteBuffer(sBuff);

  // brep header 
  smos_sprintf(sBuff,         _T("[0x%p]"), this);
  smos_sprintf(sBuffForFile,  _T("[%s]"),   _T("notNULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmPolyBrep::DumpPolyVertices

/*******************************************************************//**
PURPOSE: Construct a triangle bag.

NOTES: 
***********************************************************************/
SmTriangleBag::SmTriangleBag(ULONG lNumTriPerBlock)
{
  m_vTriMgr.Initialize(ALIGN_SIZE(sizeof(SmTriangle)),lNumTriPerBlock);
}

/*******************************************************************//**
PURPOSE: Destructor for the triangle bag.

NOTES: 
***********************************************************************/
SmTriangleBag::~SmTriangleBag()
{
  // clear all internal member values
  m_vTriangles.RemoveAll() ;
  m_vTriMgr.ReSet() ;
  m_vBBox.Init() ;

} // end SmTriangleBag destructor

/*******************************************************************//**
PURPOSE: Add a triangle to the bag.

NOTES: 
***********************************************************************/
SmStatus SmTriangleBag::AddTriangle
 (const SmPoint3d & rP1,             // in :
  const SmPoint3d & rP2,             // in :
  const SmPoint3d & rP3,             // in :
  SmTriangle     *& rpNewTriangle)   // out:
{
   SmTriangle *pTri = (SmTriangle*)m_vTriMgr.GetNewElement();
   NER(pTri);
   m_vTriangles.Add(pTri);
   pTri->m_sPoints[0] = rP1;
   pTri->m_sPoints[1] = rP2;
   pTri->m_sPoints[2] = rP3;
   m_vBBox.AddPoint3d(rP1);
   m_vBBox.AddPoint3d(rP2);
   m_vBBox.AddPoint3d(rP3);
   if(rpNewTriangle) { rpNewTriangle = pTri ; }
   return SM_SUCCESS;

} // end SmTriangleBag::AddTriangle

/*******************************************************************//**
PURPOSE: Get a triangle from the bag.

NOTES: 
***********************************************************************/
SmStatus SmTriangleBag::GetTriangle
 (long index,
  SmPoint3d & rP1,
  SmPoint3d & rP2,
  SmPoint3d & rP3)
 const
{
  SmTriangle *pTri = m_vTriangles[index];
  rP1 = pTri->m_sPoints[0];
  rP2 = pTri->m_sPoints[1];
  rP3 = pTri->m_sPoints[2];
  return SM_SUCCESS;

} // end SmTriangleBag::GetTriangle

/*******************************************************************//**
PURPOSE: Split a triangle bag into triangles which intersect the box
    and triangles which do not intersect the box.

NOTES: 
***********************************************************************/
SmStatus SmTriangleBag::SplitBag
 (const SmContext  & crContext,
  const SmExtent3d & crBBox,
  SmTriangleBag   *& rpNewBagInBox,
  SmTriangleBag   *& rpNewBagNotInBox)
{
  rpNewBagInBox = NULL;
  rpNewBagNotInBox = NULL;
  SmTriangleBag *pBagIn = new(crContext) SmTriangleBag(); NER(pBagIn);
  SmTriangleBag *pBagOut = new(crContext) SmTriangleBag(); NER(pBagOut);
  SmObjDelete sClean1(pBagIn);
  SmObjDelete sClean2(pBagOut);

  SmTriangle *pNewTri;
  ULONG ii ;
  for(ii=0;ii<m_vTriangles.GetSize();ii++){
      SmTriangle *pTri = m_vTriangles[ii];
      if(crBBox.ContainsPoint3d(pTri->m_sPoints[0]) ||
          crBBox.ContainsPoint3d(pTri->m_sPoints[1]) ||
          crBBox.ContainsPoint3d(pTri->m_sPoints[2]) ) {
          SER(pBagIn->AddTriangle(pTri->m_sPoints[0],pTri->m_sPoints[1],pTri->m_sPoints[2],pNewTri));
      }
      else {
          SER(pBagOut->AddTriangle(pTri->m_sPoints[0],pTri->m_sPoints[1],pTri->m_sPoints[2],pNewTri));
      }
  }

  sClean1.Clear(); sClean2.Clear();
  rpNewBagInBox = pBagIn;
  rpNewBagNotInBox = pBagOut;
  return SM_SUCCESS;
}

/*******************************************************************//**
PURPOSE: Read the triangles from a STL file.

NOTES: 
***********************************************************************/
SmStatus SmTriangleBag::ReadFromSTLFile
 (const SmContext & crContext,
  const TCHAR     * cInputFileName,        
  SmTriangleBag  *& rpNewTriangleBag,
  SmFileType        eType)
{
  rpNewTriangleBag = NULL;

  SmTriangleBag *pBag = new (crContext) SmTriangleBag();
  SmObjDelete    sClean1(pBag);

#define MAXSIZE 512
  std::ifstream fin2;
  if(eType == SM_ASCII) 
    { fin2.open(cInputFileName, SM_IOS::in | SM_IOS_NOCREATE); }
  else // SM_BINARY
    { fin2.open(cInputFileName, SM_IOS::in | SM_IOS_BINARY | SM_IOS_NOCREATE); }
    

  // check the stream
  if(fin2.fail() != 0 || !fin2.good()) 
    { 
#ifdef SM_DEBUG_CODE
      TCHAR sBuff[SM_TBLOCK_SIZE];
      smos_sprintf(sBuff,_T("Failed SmTriangleBag::ReadFromSTLFile(\"%s\") : std::istream::open()"), cInputFileName) ;
      SER_MSG(SM_ERR_INVALID_INPUT, sBuff);
#else // no SM_DEBUG_CODE
      SER(SM_ERR_INVALID_INPUT);
#endif // no SM_DEBUG_CODE
    }

  // locals
  char         sBuff[MAXSIZE];
  SmExtent3d   sBBox;
  ULONG        lFaceCount = 0; 
  SmTriangle * pTri;

  if(eType == SM_ASCII) 
    {
      // Read ASCII
      fin2.getline(sBuff,MAXSIZE);
      //sscanf(sBuff,"solid STL file created by SMLib"));
      while (TRUE) 
        {
          fin2.getline(sBuff,MAXSIZE);
          if(strncmp(sBuff,"endsolid",8) == 0) 
            {
              fin2.close();
              break;
            }

          SmPoint3d sP1,sP2,sP3;
          SmVector3d sNormal;
          sscanf(sBuff," facet normal %lf %lf %lf",
                 &sNormal.x,&sNormal.y,&sNormal.z);

          if(sNormal.Length() < SM_EFF_ZERO) 
            {
              SER(SM_ERR);
            }

          lFaceCount++;
          sNormal.Unitize();
          fin2.getline(sBuff,MAXSIZE); sscanf(sBuff," outer loop");
          fin2.getline(sBuff,MAXSIZE); sscanf(sBuff," vertex %lf %lf %lf",&sP1.x,&sP1.y,&sP1.z);
          fin2.getline(sBuff,MAXSIZE); sscanf(sBuff,"  vertex %lf %lf %lf",&sP2.x,&sP2.y,&sP2.z);
          fin2.getline(sBuff,MAXSIZE); sscanf(sBuff," vertex %lf %lf %lf",&sP3.x,&sP3.y,&sP3.z);
          fin2.getline(sBuff,MAXSIZE); sscanf(sBuff," endloop");
          fin2.getline(sBuff,MAXSIZE); sscanf(sBuff," endfacet");
          sBBox.AddPoint3d(sP1);
          sBBox.AddPoint3d(sP2);
          sBBox.AddPoint3d(sP3);
          pBag->AddTriangle(sP1,sP2,sP3,pTri);
        }
    }  // end ASCII
  else // BINARY
    { 
      fin2.read(sBuff,sizeof(char)*80);
      fin2.read((char*)&lFaceCount,sizeof(ULONG));
      ULONG ii ;

      for(ii=0;ii<lFaceCount;ii++)
        {
          float sVec[12];
          fin2.read((char*)sVec,sizeof(float)*12);
          char sPadd[2];
          fin2.read(sPadd,sizeof(char)*2);
          SmPoint3d sPnts[3];
          ULONG iv ;
          for(iv=0;iv<3;iv++)
            {
              sPnts[iv].x = sVec[3*iv+3];
              sPnts[iv].y = sVec[3*iv+4];
              sPnts[iv].z = sVec[3*iv+5];
              sBBox.AddPoint3d(sPnts[iv]);
            }
          pBag->AddTriangle(sPnts[0],sPnts[1],sPnts[2],pTri);
        }
    }

  fin2.close();

  sClean1.Clear();
  pBag->m_vBBox    = sBBox;
  rpNewTriangleBag = pBag;
  return SM_SUCCESS;

} // end SmTriangleBag::ReadFromSTLFile

/*******************************************************************//**
PURPOSE: Create a PolyBrep from this SmTriangleBag

NOTES: Returned NewPolyBrep has been run through SmPolyBrep::Stitch().

       As such, it has no coincident PolyVertices or PolyEdges.
       All adjacent triangles have been organized into connected neighbors
       and put into common PolyShells and PolyRegions.
  
***********************************************************************/
SmStatus SmTriangleBag::CreatePolyBrep
 (const SmContext & crContext,
  SmPolyBrep     *& rpNewPolyBrep) 
 const
{
  // Now we should have a bounding box that can be used to create a spatial
  // tree for vertices so that we don't duplicate them when reading in.
  ULONG   lTreeInitialize = smos_Max(m_vTriangles.GetSize()/10,100);
  SmTree *pVertTree       = new (crContext) SmTree(m_vBBox,lTreeInitialize,lTreeInitialize/10);
  NER(pVertTree);
  SmObjDelete sCleanTree(pVertTree);
    
  // We can only use 6 for tolerance.
  // Have read in all polygons
  // Adjust tolerances based on the size of the brep
  ULONG ii, jj ;
  SmVector3d  sSize      = m_vBBox.GetSize();
  double      dLeng      = sSize.Length();
  SmZoneTol3d sZoneTol3d = SM_EFF_ZERO_SQRT;  // Eight Decimal places in STL Files
  SmZoneTol3d dTolSq     = sZoneTol3d*sZoneTol3d;
  sZoneTol3d *= dLeng;

  ULONG lNum   = m_vTriangles.GetSize();
  ULONG lNumV  = lNum*4;
  ULONG lNumE  = lNum*4;
  ULONG lNumL  = lNum*2;
  ULONG lNumCF = 16;
  ULONG lNumF  = lNum*2;
  ULONG lNumS  = lNum;
  ULONG lNumR  = 16;
  SmPolyBrep * pPolyBrep = new (crContext) SmPolyBrep(sZoneTol3d,
                                                      lNumV +
                                                      lNumE +
                                                      lNumL +
                                                      lNumCF +
                                                      lNumF +
                                                      lNumS +
                                                      lNumR);
  SM_PTR_ARRAY(sObjects, SmObject, 32); // SmTArray<SmObject*>  

  SmPolyShell *pPolyShell  = NULL;
  ULONG        lFaceCount2 = 0;
 // ULONG lReadCount = 0;
 // SmBoolean bReverseNormals = FALSE;
 // sscanf(sBuff,"solid STL file created by SMLib"));
 // SmBoolean bDone = FALSE;

  for(ii=0;ii<m_vTriangles.GetSize();ii++)
    {
      SmTriangle *pTri = m_vTriangles[ii];
      SmPoint3d sP1 = pTri->m_sPoints[0];        
      SmPoint3d sP2 = pTri->m_sPoints[1];
      SmPoint3d sP3 = pTri->m_sPoints[2];
        
      SmExtent3d sPolyBBox;

      sPolyBBox.AddPoint3d(sP1);
      sPolyBBox.AddPoint3d(sP3);
      sPolyBBox.AddPoint3d(sP2);
      SER(pVertTree->GetObjectsInBox(sPolyBBox,sObjects));
      SmPolyVertex *pV1 = NULL;
      SmPolyVertex *pV2 = NULL;
      SmPolyVertex *pV3 = NULL;

      for(jj=0;jj<sObjects.GetSize();jj++)
        {
          SmPolyVertex *pPVertFound = SM_CAST_PTR(SmPolyVertex,sObjects[jj]);
          SmPoint3d sPnt = pPVertFound->GetPoint();
          if(pV1 == NULL && sPnt.DistanceBetweenSquared(sP1) < dTolSq) { pV1 = pPVertFound; }
          if(pV2 == NULL && sPnt.DistanceBetweenSquared(sP2) < dTolSq) { pV2 = pPVertFound; }
          if(pV3 == NULL && sPnt.DistanceBetweenSquared(sP3) < dTolSq) { pV3 = pPVertFound; }
        }

      // Check to see if we have a collapse of the vertices
      if(pV1 && pV1 == pV2)
        { continue ; }
      if(pV1 && pV1 == pV3)
        { continue ; }
      if(pV2 && pV2 == pV3)
        { continue ; }

      if(sP1.DistanceBetweenSquared(sP2) < dTolSq)
        { continue ; }
      if(sP2.DistanceBetweenSquared(sP3) < dTolSq)
        { continue ; }      
      if(sP1.DistanceBetweenSquared(sP3) < dTolSq)
        { continue ; }

      SmVector3d sNorm ;
      sP1.NormalToPlane(sP2, sP3, sNorm) ;

      // place all newPolyFaces into common PolyShell - it's built on the first new SmPolyFace call
      SmPolyFace *pPolyFace = new (pPolyBrep) SmPolyFace(sZoneTol3d,
                                                         pPolyBrep,
                                                         NULL,
                                                         pPolyShell,
                                                         sNorm.IsInitialized() ? &sNorm : NULL);
      lFaceCount2 ++;

      pPolyFace->SetIndexValue(lFaceCount2);
      if(pPolyShell == NULL) 
        {
          pPolyShell = pPolyFace->GetPolyShell();
        }

      SmPolyLoop *pPolyLoop = NULL;
      SmPolyEdge *pEdge1, *pEdge2, *pEdge3;

      SER(pPolyFace->StartPolyEdgeLoop(pPolyLoop));
      SER(pPolyLoop->AddPolyEdge(sZoneTol3d, sP1, sP2, pV1, pV2, pPolyBrep, pEdge1));
      SER(pPolyLoop->AddPolyEdge(sZoneTol3d, sP2, sP3, pV2, pV3, pPolyBrep, pEdge2));
      SER(pPolyLoop->AddPolyEdge(sZoneTol3d, sP3, sP1, pV3, pV1, pPolyBrep, pEdge3));
      SER(pPolyLoop->FinishPolyEdgeLoop(pPolyBrep));

      if(pV1 == NULL) 
        {
          pV1 = pEdge1->GetStartPolyVertex();
          SmExtent3d sVertBBox(pV1->GetPoint(),pV1->GetPoint());
          SER(pVertTree->AddToSpatialTree(sVertBBox,pV1));
        }
      if(pV2 == NULL) 
        {
          pV2 = pEdge2->GetStartPolyVertex();
          SmExtent3d sVertBBox(pV2->GetPoint(),pV2->GetPoint());
          SER(pVertTree->AddToSpatialTree(sVertBBox,pV2));
        }
      if(pV3 == NULL) 
        {
          pV3 = pEdge3->GetStartPolyVertex();
          SmExtent3d sVertBBox(pV3->GetPoint(),pV3->GetPoint());
          SER(pVertTree->AddToSpatialTree(sVertBBox,pV3));
        }

      pPolyFace->m_dMaxDeviation = 0.0;
      pPolyFace->GetNormal(TRUE,TRUE);
    }

  // Clean up the vertex tree to free memeory for stitching
  sCleanTree.Clear();
  SM_ASSERT(pVertTree != NULL) ; delete pVertTree ; pVertTree = NULL ;

  // Stitch all SmPolyFace's
  ULONG lNumEdgesStitched;
  ULONG lNumberLaminaRemaining;
  SER(pPolyBrep->Stitch(sZoneTol3d,          // note: increments unlocked mark value
                     TRUE,
                     FALSE,
                     TRUE,
                     lNumEdgesStitched,
                     lNumberLaminaRemaining));

  rpNewPolyBrep = pPolyBrep;

  // all done
  return SM_SUCCESS;

} // end SmTriangleBag::CreatePolyBrep

