/*******************************************************************//**
PURPOSE: switch SmPolyVertex mem allocation from regular new to
         internal SmPolyBrep::m_sVMgr SmMemBlockMgr managed memory
NOTES:
***********************************************************************/
void *SmPolyVertex::operator new
 (size_t       size,     // NotUsed: in : 
  SmPolyBrep * pPBrep)   // in : 
{ 
  SM_REF1(size) ;
  // return value
  SmPolyVertex *pRet  = (SmPolyVertex*)pPBrep->m_sMgr.Allocate(sizeof(SmPolyVertex));

  // local management to mimic SmObject::operator new
  const SmContext * cpContext = pPBrep->GetContext();
  pRet->m_cpContext           = cpContext;

  // hack to talk to SmObject constructor
  SmThreadLocalStorage::SetBeenThroughNew(TRUE, pRet) ; // TRUE = remember this, FALSE = forget this
  return (void*)pRet;

} // end *SmPolyVertex::operator new

