/*******************************************************************//**
PURPOSE: Add a (Copy Pointer, Orig Pointer) pair entry to
            the SmCopyPolyBrepMap

NOTES:
***********************************************************************/
void SmCopyPolyBrepMap::SetAt
  (SmTopology *pCopyObj,      // in : Copy of orig Topology object
   SmTopology *pOrigObj)      // in : Orig Topology object being copied
{
  // switch on SmTopology type
  SM_ASSERT(pOrigObj==NULL || pCopyObj->GetType() == pOrigObj->GetType()) ;
  switch(pOrigObj->GetType())
    {
      case SmPolyRegion_TYPE    : m_sMapPolyRegions.   Insert((SmPolyRegion*) pCopyObj, (SmPolyRegion*) pOrigObj) ; break ;
      case SmPolyShell_TYPE     : m_sMapPolyShells.    Insert((SmPolyShell*)  pCopyObj, (SmPolyShell*)  pOrigObj) ; break ;
      case SmPolyFace_TYPE      : m_sMapPolyFaces.     Insert((SmPolyFace*)   pCopyObj, (SmPolyFace*)   pOrigObj) ; break ;
      case SmCPolyFace_TYPE     : m_sMapCPolyFaces.    Insert((SmCPolyFace*)  pCopyObj, (SmCPolyFace*)  pOrigObj) ; break ;
      case SmPolyLoop_TYPE      : m_sMapPolyLoops.     Insert((SmPolyLoop*)   pCopyObj, (SmPolyLoop*)   pOrigObj) ; break ;
      case SmPolyEdge_TYPE      : m_sMapPolyEdges.     Insert((SmPolyEdge*)   pCopyObj, (SmPolyEdge*)   pOrigObj) ; break ;
      case SmPolyVertex_TYPE    : m_sMapPolyVertexs.   Insert((SmPolyVertex*) pCopyObj, (SmPolyVertex*) pOrigObj) ; break ;
      default :  WARN(_T("bad SmPolyCopyPolyBrepMap entry - unexpected object type")) ;
    } // end switch on type

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw 
  if(bDebugMe)
    {
      this->Dump(FALSE) ;
      this->Dump(TRUE) ;
    }
#endif // SM_DEBUG_CODE

} // end SmCopyPolyBrepMap::SetAt

/*******************************************************************//**
PURPOSE: Add a (Copy Pointer, Orig Pointer) pair entry to
            the SmCopyPolyBrepMap

NOTES:
***********************************************************************/
void SmCopyPolyBrepMap::SetAt
  (ULONG       lIndex,        // in : Index assigned to orig topology object
   SmTopology *pOrigObj)      // in : Orig Topology object being copied
{
  // switch on SmTopology type
  SM_ASSERT(pOrigObj!=NULL) ;

  switch(pOrigObj->GetType())
    {
      case SmPolyRegion_TYPE    : 
        if ( lIndex >= m_sPolyRegionsIndex.GetSize() )
          { m_sPolyRegionsIndex.SetSize( 2*(lIndex+1) ); }
        m_sPolyRegionsIndex.SetAt(lIndex, SM_CAST_PTR(SmPolyRegion, pOrigObj) ) ; 
        break ;
      case SmPolyShell_TYPE     : 
        if ( lIndex >= m_sPolyShellsIndex.GetSize() )
          { m_sPolyShellsIndex.SetSize( 2*(lIndex+1) ); }
        m_sPolyShellsIndex.SetAt(lIndex,SM_CAST_PTR(SmPolyShell, pOrigObj) );
        break ;
      case SmPolyFace_TYPE      : 
        if ( lIndex >= m_sPolyFacesIndex.GetSize() )
          { m_sPolyFacesIndex.SetSize( 2*(lIndex+1) ); }
        m_sPolyFacesIndex.SetAt(lIndex, SM_CAST_PTR(SmPolyFace, pOrigObj)) ; 
        break ;
      case SmCPolyFace_TYPE     : 
        if ( lIndex >= m_sCPolyFacesIndex.GetSize() )
          { m_sCPolyFacesIndex.SetSize( 2*(lIndex+1) ); }
        m_sCPolyFacesIndex.SetAt(lIndex,SM_CAST_PTR(SmCPolyFace, pOrigObj) ) ; 
        break ;
      case SmPolyLoop_TYPE      :
        if ( lIndex >= m_sPolyLoopsIndex.GetSize() )
          { m_sPolyLoopsIndex.SetSize( 2*(lIndex+1) ); }
        m_sPolyLoopsIndex.SetAt(lIndex, SM_CAST_PTR(SmPolyLoop,pOrigObj)) ; 
        break ;
      case SmPolyEdge_TYPE      : 
        if ( lIndex >= m_sPolyEdgesIndex.GetSize() )
          { m_sPolyEdgesIndex.SetSize( 2*(lIndex+1) ); }
        m_sPolyEdgesIndex.SetAt(lIndex, SM_CAST_PTR(SmPolyEdge, pOrigObj)) ; 
        break ;
      case SmPolyVertex_TYPE    : 
        if ( lIndex >= m_sPolyVertexsIndex.GetSize() )
          { m_sPolyVertexsIndex.SetSize( 2*(lIndex+1) ); }
        m_sPolyVertexsIndex.SetAt(lIndex, SM_CAST_PTR(SmPolyVertex, pOrigObj)) ; 
        break ;
      default :  WARN(_T("bad SmPolyCopyPolyBrepMap entry - unexpected object type")) ;
    } // end switch on type

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw 
  if(bDebugMe)
    {
      this->Dump(FALSE) ;
      this->Dump(TRUE) ;
    }
#endif // SM_DEBUG_CODE

} // end SmCopyPolyBrepMap::SetAt

/*******************************************************************//**
PURPOSE: Get an Orig Pointer value given a Copy Pointer value.

NOTES:
***********************************************************************/
SmTopology *SmCopyPolyBrepMap::GetAt
  (SmTopology *pCopyObj)  const    // in : Orig Topology object being copied
{
  // return value
  SmTopology *pRtn = NULL ;

  if( pCopyObj == NULL )
    { return pRtn; }

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw 
  if(bDebugMe)
    {
      this->Dump(FALSE) ;
      this->Dump(TRUE) ;
    }
#endif // SM_DEBUG_CODE

  // switch on SmTopology type
  switch(pCopyObj->GetType())
    {
      case SmPolyRegion_TYPE    : pRtn = (SmTopology *)m_sMapPolyRegions.   At((SmPolyRegion*) pCopyObj) ; break ;
      case SmPolyShell_TYPE     : pRtn = (SmTopology *)m_sMapPolyShells.    At((SmPolyShell*)  pCopyObj) ; break ;
      case SmPolyFace_TYPE      : pRtn = (SmTopology *)m_sMapPolyFaces.     At((SmPolyFace*)   pCopyObj) ; break ;
      case SmCPolyFace_TYPE     : pRtn = (SmTopology *)m_sMapCPolyFaces.    At((SmCPolyFace*)  pCopyObj) ; break ;
      case SmPolyLoop_TYPE      : pRtn = (SmTopology *)m_sMapPolyLoops.     At((SmPolyLoop*)   pCopyObj) ; break ;
      case SmPolyEdge_TYPE      : pRtn = (SmTopology *)m_sMapPolyEdges.     At((SmPolyEdge*)   pCopyObj) ; break ;
      case SmPolyVertex_TYPE    : pRtn = (SmTopology *)m_sMapPolyVertexs.   At((SmPolyVertex*) pCopyObj) ; break ;
      default : WARN(_T("bad SmCopyPolyBrepMap query - unexpected object type")) ;
    } // end switch on type

  SM_ASSERT(   pRtn != NULL
            && pCopyObj->GetType() == pRtn->GetType()) ;

  // all done
  return(pRtn) ;

} // end SmCopyPolyBrepMap::GetValueAt

/*******************************************************************//**
PURPOSE: Get an Orig Pointer value given an index value and a type value

NOTES:
***********************************************************************/
SmTopology *SmCopyPolyBrepMap::GetAt
 (ULONG   lIndex,       // in : index key
  SM_TYPE lType)        // in : oneof SmPolyRegion_TYPE, SmPolyShell_TYPE, . . .
  const    // in : Orig Topology object being copied
{
  // return value
  SmTopology *pRtn = NULL ;

  if( lIndex == 0 )
    { return pRtn; }

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw 
  if(bDebugMe)
    {
      this->Dump(FALSE) ;
      this->Dump(TRUE) ;
    }
#endif // SM_DEBUG_CODE

  // switch on SmTopology type
  switch(lType)
    {
      case SmPolyRegion_TYPE    : pRtn = (SmTopology *)m_sPolyRegionsIndex.GetAt(lIndex) ; break ;
      case SmPolyShell_TYPE     : pRtn = (SmTopology *)m_sPolyShellsIndex. GetAt(lIndex) ; break ;
      case SmPolyFace_TYPE      : pRtn = (SmTopology *)m_sPolyFacesIndex.  GetAt(lIndex) ; break ;
      case SmCPolyFace_TYPE     : pRtn = (SmTopology *)m_sCPolyFacesIndex. GetAt(lIndex) ; break ;
      case SmPolyLoop_TYPE      : pRtn = (SmTopology *)m_sPolyLoopsIndex.  GetAt(lIndex) ; break ;
      case SmPolyEdge_TYPE      : pRtn = (SmTopology *)m_sPolyEdgesIndex.  GetAt(lIndex) ; break ;
      case SmPolyVertex_TYPE    : pRtn = (SmTopology *)m_sPolyVertexsIndex.GetAt(lIndex) ; break ;
      default : WARN(_T("bad SmCopyPolyBrepMap query - unexpected object type")) ;
    } // end switch on type

  SM_ASSERT(   pRtn  != NULL
            && lType == pRtn->GetType()) ;

  // all done
  return(pRtn) ;

} // end SmCopyPolyBrepMap::GetValueAt

/*******************************************************************//**
PURPOSE: Set size of m_sPoly*Index mapping

NOTES:
***********************************************************************/
void SmCopyPolyBrepMap::SetIndexSize
 (ULONG   lSize,       // in : index size
  SM_TYPE lType)       // in : oneof SmPolyRegion_TYPE, SmPolyShell_TYPE, . . .
{
  // switch on SmTopology type
  switch(lType)
    {
      case SmPolyRegion_TYPE    : m_sPolyRegionsIndex.SetSize(lSize) ; break ;
      case SmPolyShell_TYPE     : m_sPolyShellsIndex. SetSize(lSize) ; break ;
      case SmPolyFace_TYPE      : m_sPolyFacesIndex.  SetSize(lSize) ; break ;
      case SmCPolyFace_TYPE     : m_sCPolyFacesIndex. SetSize(lSize) ; break ;
      case SmPolyLoop_TYPE      : m_sPolyLoopsIndex.  SetSize(lSize) ; break ;
      case SmPolyEdge_TYPE      : m_sPolyEdgesIndex.  SetSize(lSize) ; break ;
      case SmPolyVertex_TYPE    : m_sPolyVertexsIndex.SetSize(lSize) ; break ;
      default : WARN(_T("bad SmCopyPolyBrepMap query - unexpected object type")) ;
    } // end switch on type

} // end SmCopyPolyBrepMap::SetIndexSize

/*******************************************************************//**
PURPOSE: Pretty print

NOTES:
***********************************************************************/
void SmCopyPolyBrepMap::Dump() const
{
  // pass the call along
  Dump(FALSE) ;

} // end SmCopyPolyBrepMap::Dump

/*******************************************************************//**
PURPOSE: Pretty print

NOTES:
***********************************************************************/
void SmCopyPolyBrepMap::Dump(SmBoolean bFull) const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE] ;

  // SmCopyPolyBrepMap Pointer
  smos_sprintf(sBuff,_T("\nSmCopyPolyBrepMap = 0x%p, Orig/Copy PolyBreps[0x%p, 0x%p] "), 
             this, 
             m_pOrigPolyBrep, 
             m_pCopyPolyBrep);
  smos_sprintf(sBuffForFile,_T("\nSmCopyPolyBrepMap = %s,Orig/SmPolyBrep = [%s, %s] "),
             _T("notNULL"),
             m_pOrigPolyBrep ? _T("notNULL") : _T("NULL"),
             m_pCopyPolyBrep ? _T("notNULL") : _T("NULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

  // labels, counts, and maps
#define DUMP_PTR_MAP(a) \
  smos_sprintf(sBuff,_T("\n%s [items = %ld]"), _T(#a), (a).Count()) ; \
  smos_WriteBuffer(sBuff) ;                                           \
  if(bFull) { (a).Dump() ; }

  DUMP_PTR_MAP(m_sMapPolyRegions) ;
  DUMP_PTR_MAP(m_sMapPolyShells) ;
  DUMP_PTR_MAP(m_sMapPolyFaces) ;
  DUMP_PTR_MAP(m_sMapCPolyFaces) ;
  DUMP_PTR_MAP(m_sMapPolyLoops) ;
  DUMP_PTR_MAP(m_sMapPolyEdges) ;
  DUMP_PTR_MAP(m_sMapPolyVertexs) ;
#undef DUMP_PTR_MAP  

} // end SmCopyPolyBrepMap::Dump
